import { t, type DeepSet } from "../types";

/** Level 5 · Disciple Maker: the Spirit-led teaching for each lesson. */
export const DEEP: DeepSet = {
  "jesus-way-of-discipleship": {
    revelation: t(
      "Jesus did not build a program and then look for people; He gave Himself to a few people, and the program was His life shared with them.",
      "Hindi gumawa si Hesus ng programa saka naghanap ng tao; ibinigay Niya ang sarili Niya sa iilang tao, at ang \"programa\" ay ang buhay Niyang ibinahagi sa kanila."
    ),
    mainTruth: t(
      "Before Jesus chose the Twelve, He spent the whole night praying to God (Luke 6:12-16). Then He appointed them first \"that they might be with Him,\" and only then \"that He might send them out to preach and to have authority\" (Mark 3:13-15). The mark of the disciples He was forming would not be their skill but their love: \"By this everyone will know that you are My disciples, if you love one another\" (John 13:34-35). Jesus' way is prayer first, presence second, sending third, and love through it all.",
      "Bago pinili ni Hesus ang Labindalawa, magdamag Siyang nanalangin sa Diyos (Lucas 6:12-16). Pagkatapos, hinirang Niya sila una sa lahat \"upang sila'y makasama Niya,\" at saka pa lang \"upang suguin Niya sila na mangaral at magkaroon ng kapangyarihan\" (Marcos 3:13-15). Ang tatak ng mga alagad na hinuhubog Niya ay hindi ang galing nila kundi ang pag-ibig nila: \"Dito makikilala ng lahat na kayo'y mga alagad Ko, kung kayo'y nag-iibigan\" (Juan 13:34-35). Ganito ang paraan ni Hesus: panalangin muna, presensya pangalawa, pagsusugo pangatlo, at pag-ibig sa kabuuan."
    ),
    insight: [
      t(
        "Many of us want to make disciples the way we run events: a schedule, a venue, a handout. Jesus' first strategy was strangely simple: \"Come, be with Me.\" The disciples learned how He prayed by hearing Him pray, how He handled rejection by watching Him get rejected, how He treated sinners by eating at their tables. Most of what they learned was caught, not taught. You cannot give someone a life you only describe from a stage.",
        "Marami sa atin ang gustong gumawa ng alagad gaya ng pagpapatakbo ng event: may iskedyul, may venue, may handout. Kakaibang simple ang unang estratehiya ni Hesus: \"Halika, sumama ka sa Akin.\" Natutunan ng mga alagad kung paano Siya manalangin dahil narinig nila Siyang nananalangin, kung paano harapin ang pagtanggi dahil nakita nilang tinanggihan Siya, kung paano tratuhin ang makasalanan dahil kumain Siya sa hapag nila. Karamihan sa natutunan nila ay nahawa, hindi itinuro. Hindi mo maibibigay sa iba ang buhay na inilalarawan mo lang mula sa entablado."
      ),
      t(
        "Notice also whom Jesus prayed over all night: a fisherman with a quick temper, a tax collector who worked for Rome, a zealot who hated Rome, and Judas, who would betray Him. Jesus did not pick the finished; He picked the willing and then poured His life into them for three years. If you are waiting for \"ready\" people before you start discipling, you will wait forever. God sends you unfinished people because He sent Jesus to unfinished you.",
        "Pansinin din kung sino ang ipinanalangin ni Hesus nang magdamag: isang mangingisdang mainitin ang ulo, isang maniningil ng buwis na nagtatrabaho para sa Roma, isang zealot na galit sa Roma, at si Judas na magtataksil sa Kanya. Hindi pumili si Hesus ng tapos na; pinili Niya ang handang sumunod at ibinuhos ang buhay Niya sa kanila sa loob ng tatlong taon. Kung hinihintay mo ang mga taong \"handa na\" bago ka magdisciple, maghihintay ka habambuhay. Nagpapadala ang Diyos sa iyo ng mga hindi pa tapos dahil ipinadala Niya si Hesus sa hindi pa tapos na ikaw."
      ),
    ],
    life: [
      t(
        "Kuya Ramon, a welder in Jubail, was not a preacher. He simply invited a younger Filipino from his camp to eat with him every Friday after service. They washed dishes together, prayed over each other's families back home, and read one chapter of Mark each week. Two years later, that young man was doing the same thing with three new workers. Nobody announced it as a ministry. It was just a life shared at a small table, and it multiplied.",
        "Si Kuya Ramon, isang welder sa Jubail, ay hindi mangangaral. Inaanyayahan lang niya ang isang mas batang Pinoy sa kampo nila na kumain kasama niya tuwing Biyernes pagkatapos ng service. Sabay silang naghuhugas ng plato, ipinapanalangin ang pamilya ng isa't isa sa Pilipinas, at nagbabasa ng isang kabanata ng Marcos bawat linggo. Makalipas ang dalawang taon, ganoon na rin ang ginagawa ng binatang iyon sa tatlong bagong trabahador. Walang nag-anunsyo na ministry ito. Buhay lang na ibinahagi sa maliit na mesa, at dumami."
      ),
      t(
        "Think of how a Filipino child learns to cook adobo. Nobody gives her a seminar. She stands beside Lola in the kitchen, watches, tastes, gets scolded gently for too much soy sauce, and one day cooks it herself for the family. That is discipleship. Your kitchen, your jeepney ride, your shift break and your video call can all become the place where someone learns to follow Jesus by watching you follow Him.",
        "Isipin kung paano natututo ang isang batang Pinoy na magluto ng adobo. Walang nagbibigay sa kanya ng seminar. Tumatayo siya sa tabi ni Lola sa kusina, nanonood, tumitikim, napapagalitan nang mahinahon dahil sobra sa toyo, at isang araw siya na ang nagluluto para sa pamilya. Iyan ang discipleship. Ang kusina mo, ang biyahe mo sa jeep, ang break mo sa trabaho at ang video call mo ay puwedeng maging lugar kung saan may natututong sumunod kay Hesus dahil nakikita ka niyang sumusunod sa Kanya."
      ),
    ],
    twist: t(
      "We assume the greatest thing Jesus gave the Twelve was His teaching. But Mark 3:14 puts \"to be with Him\" before preaching and power. The first calling of a disciple is not usefulness but nearness. And here is the twist for disciple makers: the best thing you can give the people you lead is not your lessons but your life, especially the honest parts where they see you repent, pray and keep going. Your weakness, handled with Jesus, may teach them more than your strength.",
      "Akala natin ang pinakamahalagang ibinigay ni Hesus sa Labindalawa ay ang mga turo Niya. Pero sa Marcos 3:14, nauna ang \"upang makasama Niya\" bago ang pangangaral at kapangyarihan. Ang unang tawag sa alagad ay hindi pagiging kapaki-pakinabang kundi pagiging malapit. At ito ang twist para sa mga gumagawa ng alagad: ang pinakamagandang maibibigay mo sa mga inaakay mo ay hindi ang mga leksyon mo kundi ang buhay mo, lalo na ang tapat na bahagi kung saan nakikita nilang nagsisisi ka, nananalangin at nagpapatuloy. Ang kahinaan mong dinadala kay Hesus ay maaaring mas maraming maituro kaysa sa lakas mo."
    ),
    confirm: [
      t("1 Thessalonians 2:8: Paul shared not only the gospel but his own life with them.", "1 Tesalonica 2:8: ibinahagi ni Pablo hindi lang ang ebanghelyo kundi pati ang sarili niyang buhay."),
      t("Acts 4:13: the leaders recognized that Peter and John had been with Jesus.", "Gawa 4:13: napansin ng mga pinuno na sina Pedro at Juan ay nakasama ni Hesus."),
      t("1 Corinthians 11:1: \"Follow my example, as I follow the example of Christ.\"", "1 Corinto 11:1: \"Tularan ninyo ako, gaya ng pagtulad ko kay Cristo.\""),
      t("Matthew 28:19-20: go and make disciples, teaching them to obey, and He is with us always.", "Mateo 28:19-20: humayo at gumawa ng alagad, turuan silang sumunod, at kasama natin Siya palagi."),
    ],
    heart: [
      t(
        "Move from performing ministry to sharing life. People do not need a perfect model; they need an honest, present follower of Jesus they can walk beside.",
        "Lumipat mula sa pagtatanghal ng ministeryo tungo sa pagbabahagi ng buhay. Hindi kailangan ng mga tao ng perpektong modelo; kailangan nila ng tapat at presenteng tagasunod ni Hesus na masasabayan nila."
      ),
      t(
        "Let prayer come before your choosing and your planning. Ask the Father whom He is giving you, and love them as Jesus loved you: patiently, personally, to the end.",
        "Hayaang mauna ang panalangin sa pagpili at pagpaplano mo. Itanong sa Ama kung sino ang ibinibigay Niya sa iyo, at mahalin sila gaya ng pagmamahal ni Hesus sa iyo: matiyaga, personal, hanggang wakas."
      ),
    ],
    questions: [
      t("Who walked with you when you were new in faith, and what did you catch from their life?", "Sino ang sumama sa iyo noong bago ka sa pananampalataya, at ano ang nahawa sa iyo mula sa buhay nila?"),
      t("Are you more comfortable teaching people than being with them? Why?", "Mas komportable ka bang turuan ang tao kaysa samahan sila? Bakit?"),
      t("If someone copied your life for a year, what would they learn about following Jesus?", "Kung may gumaya sa buhay mo sa loob ng isang taon, ano ang matututunan nila tungkol sa pagsunod kay Hesus?"),
      t("Whom has God already placed near you that you have not yet invited to walk with you?", "Sino ang inilapit na ng Diyos sa iyo na hindi mo pa naaanyayahang sumabay sa iyo?"),
    ],
    actions: [
      t("Spend one evening this week praying through your contacts list, asking the Father whom He wants you to disciple.", "Maglaan ng isang gabi ngayong linggo para ipanalangin ang listahan ng contacts mo, at itanong sa Ama kung sino ang gusto Niyang i-disciple mo."),
      t("Invite one person to share a meal, a walk or a call with you, with no agenda except to be together and pray.", "Anyayahan ang isang tao na kumain, maglakad o mag-call kasama mo, walang ibang agenda kundi magkasama at manalangin."),
      t("Choose one ordinary routine (grocery, commute, break time) and bring someone along so they can see your walk with God.", "Pumili ng isang ordinaryong gawain (pamamalengke, biyahe, break time) at isama ang isang tao para makita niya ang lakad mo kasama ang Diyos."),
    ],
    prayer: t(
      "Lord Jesus, You prayed all night before You called Your friends, and You called them first to be with You. Teach me to make disciples Your way. Slow me down so I can be present. Show me the people the Father is giving me, even the unfinished ones, because You chose unfinished me. Let my life be honest enough to follow and Your love in me strong enough to be seen. Make me a disciple who makes disciples. Amen.",
      "Panginoong Hesus, nanalangin Ka nang magdamag bago Mo tinawag ang mga kaibigan Mo, at tinawag Mo sila una sa lahat para makasama Ka. Turuan Mo akong gumawa ng alagad sa Iyong paraan. Pabagalin Mo ako para makapag-presensya ako. Ipakita Mo ang mga taong ibinibigay sa akin ng Ama, pati ang mga hindi pa tapos, dahil pinili Mo rin ako kahit hindi pa ako tapos. Gawin Mong tapat ang buhay ko para masundan, at ang pag-ibig Mo sa akin ay makita ng iba. Gawin Mo akong alagad na gumagawa ng alagad. Amen."
    ),
  },

  "leading-a-bible-study": {
    revelation: t(
      "The goal of a Bible study is not that people admire the leader's knowledge, but that they meet the living God in His Word and leave changed.",
      "Ang layunin ng Bible study ay hindi para hangaan ng mga tao ang kaalaman ng leader, kundi para makatagpo nila ang buhay na Diyos sa Kanyang Salita at umuwing binago."
    ),
    mainTruth: t(
      "When Ezra opened the Book of the Law, the people stood, worshiped and listened from morning until noon. The Levites \"read from the Book of the Law of God, making it clear and giving the meaning so that the people understood\" (Nehemiah 8:1-8). The Bereans \"received the message with great eagerness and examined the Scriptures every day\" to see if what Paul said was true (Acts 17:10-12). And Paul urges Timothy to be \"a worker who does not need to be ashamed and who correctly handles the word of truth\" (2 Timothy 2:15). A faithful leader reads clearly, explains honestly, and helps people search the Scriptures for themselves.",
      "Nang buksan ni Ezra ang Aklat ng Kautusan, tumayo ang mga tao, sumamba at nakinig mula umaga hanggang tanghali. Ang mga Levita ay \"bumasa sa Aklat ng Kautusan ng Diyos, ipinaliwanag ito nang malinaw at ibinigay ang kahulugan upang maunawaan ng mga tao\" (Nehemias 8:1-8). Ang mga taga-Berea ay \"tumanggap ng salita nang buong sigla at sinaliksik ang Kasulatan araw-araw\" para malaman kung totoo ang sinabi ni Pablo (Gawa 17:10-12). At hinihimok ni Pablo si Timoteo na maging \"manggagawang hindi dapat ikahiya, na wastong gumagamit ng salita ng katotohanan\" (2 Timoteo 2:15). Ang tapat na leader ay bumabasa nang malinaw, nagpapaliwanag nang tapat, at tumutulong sa mga tao na saliksikin mismo ang Kasulatan."
    ),
    insight: [
      t(
        "We often think a good Bible study leader is the one who talks the most and knows the most. But in Nehemiah 8 the leaders worked so that \"the people understood.\" The measure of a study is not how much was said but how much was understood and obeyed. A leader who answers every question himself trains people to depend on him. A leader who asks, \"What do you see in verse 3?\" trains people to depend on the Word and the Spirit.",
        "Madalas nating isipin na ang magaling na Bible study leader ay ang pinakamaraming sinasabi at pinakamaraming alam. Pero sa Nehemias 8, nagsikap ang mga leader para \"maunawaan ng mga tao.\" Ang sukatan ng isang pag-aaral ay hindi kung gaano karami ang nasabi kundi kung gaano karami ang naunawaan at sinunod. Ang leader na sumasagot sa lahat ng tanong ay nagtuturo sa tao na umasa sa kanya. Ang leader na nagtatanong, \"Ano ang nakikita mo sa talata 3?\" ay nagtuturo sa tao na umasa sa Salita at sa Espiritu."
      ),
      t(
        "Notice how the people in Nehemiah responded: they wept, then they rejoiced, then they obeyed by celebrating the feast the Law described (Nehemiah 8:9-17). Real Bible study touches the mind, the heart and the hands. If your group only gains information, something is missing. Always ask the Spirit to move the study from \"What does it say?\" to \"What will I do?\"",
        "Pansinin kung paano tumugon ang mga tao sa Nehemias: umiyak sila, saka nagalak, saka sumunod sa pagdiriwang ng pistang inilarawan ng Kautusan (Nehemias 8:9-17). Ang tunay na Bible study ay umaabot sa isip, puso at kamay. Kung impormasyon lang ang nakukuha ng grupo mo, may kulang. Laging hilingin sa Espiritu na dalhin ang pag-aaral mula sa \"Ano ang sinasabi nito?\" tungo sa \"Ano ang gagawin ko?\""
      ),
    ],
    life: [
      t(
        "Ate Joy led a small study for domestic helpers in Hong Kong on their Sunday off, sitting on cardboard under a footbridge. She was nervous because she had never been to Bible school. So she kept it simple: read the passage twice, ask \"What does it say? What does it mean? What will I do?\" and pray. One Sunday, after reading about the woman at the well, a quiet helper finally spoke: \"I thought God was finished with me because of my past.\" That moment did not come from a brilliant lecture. It came from a leader who made space for the Word to speak.",
        "Si Ate Joy ay nangunguna sa maliit na study para sa mga domestic helper sa Hong Kong tuwing day-off nila, nakaupo sa karton sa ilalim ng footbridge. Kinakabahan siya dahil hindi siya nag-Bible school. Kaya pinasimple niya: basahin ang talata nang dalawang beses, itanong ang \"Ano ang sinasabi? Ano ang ibig sabihin? Ano ang gagawin ko?\" at manalangin. Isang Linggo, pagkatapos basahin ang tungkol sa babae sa balon, nagsalita ang isang tahimik na helper: \"Akala ko tapos na ang Diyos sa akin dahil sa nakaraan ko.\" Hindi galing sa makinang na lecture ang sandaling iyon. Galing iyon sa leader na nagbigay ng puwang para magsalita ang Salita."
      ),
      t(
        "Preparing a study is like a carinderia cook preparing ulam. She does not cook in front of the customers; she starts early so the food is ready when they arrive. Study the passage yourself first, pray over it, let it change you, then serve it. A leader who has not been fed cannot feed others well.",
        "Ang paghahanda ng Bible study ay parang kusinero sa karinderya na naghahanda ng ulam. Hindi siya nagluluto sa harap ng mga kustomer; maaga siyang nagsisimula para handa na ang pagkain pagdating nila. Pag-aralan mo muna ang talata, ipanalangin ito, hayaan itong baguhin ka, saka mo ihain. Ang leader na hindi pa napakain ay hindi makapagpapakain nang maayos sa iba."
      ),
    ],
    twist: t(
      "We think the leader's job is to have the answers. But the Bereans were praised as \"more noble\" because they checked even the apostle Paul against the Scriptures. The Kingdom twist: a great Bible study leader is happy when the group does not simply believe him, but opens the Bible to see for themselves. Your success is not people who quote you; it is people who can open the Word without you.",
      "Akala natin trabaho ng leader na may sagot sa lahat. Pero pinuri ang mga taga-Berea bilang \"mas marangal\" dahil sinuri nila pati si apostol Pablo gamit ang Kasulatan. Ito ang Kingdom twist: ang mahusay na Bible study leader ay natutuwa kapag hindi basta naniniwala sa kanya ang grupo, kundi binubuksan nila ang Bibliya para makita mismo. Ang tagumpay mo ay hindi mga taong sumisipi sa iyo; ito ay mga taong kayang buksan ang Salita kahit wala ka."
    ),
    confirm: [
      t("Luke 24:27, 32: Jesus opened the Scriptures, and their hearts burned within them.", "Lucas 24:27, 32: binuksan ni Hesus ang Kasulatan, at nag-alab ang puso nila."),
      t("Ezra 7:10: Ezra set his heart to study the Law, to do it, and then to teach it.", "Ezra 7:10: itinalaga ni Ezra ang puso niya na pag-aralan ang Kautusan, gawin ito, at saka ituro."),
      t("James 1:22: be doers of the word, not hearers only.", "Santiago 1:22: maging tagatupad ng salita, hindi tagapakinig lamang."),
      t("Psalm 119:130: the unfolding of Your words gives light and understanding to the simple.", "Awit 119:130: ang pagbubukas ng Iyong mga salita ay nagbibigay-liwanag at unawa sa payak."),
    ],
    heart: [
      t(
        "Move from wanting to impress to wanting people to understand. Humility in a leader opens the door for the Spirit to teach.",
        "Lumipat mula sa pagnanais na makapagpahanga tungo sa pagnanais na makaunawa ang mga tao. Ang kababaang-loob ng leader ang nagbubukas ng pinto para magturo ang Espiritu."
      ),
      t(
        "Become a learner first. Let the Word search and correct you before you ever lead others through it.",
        "Maging mag-aaral muna. Hayaang saliksikin at itama ka ng Salita bago mo pangunahan ang iba rito."
      ),
    ],
    questions: [
      t("What made a Bible study you attended truly life-changing?", "Ano ang nagpabago ng buhay sa isang Bible study na dinaluhan mo?"),
      t("Do you lead to be understood or to be admired? How would your group answer that?", "Nangunguna ka ba para maunawaan o para hangaan? Paano ito sasagutin ng grupo mo?"),
      t("How much time do you spend letting the passage change you before you teach it?", "Gaano katagal mong hinahayaang baguhin ka ng talata bago mo ito ituro?"),
      t("Who in your group is quiet, and how could you make space for them to speak?", "Sino sa grupo mo ang tahimik, at paano mo sila mabibigyan ng puwang na magsalita?"),
    ],
    actions: [
      t("Choose one short passage and prepare it with the three questions: What does it say? What does it mean? What will I do?", "Pumili ng isang maikling talata at ihanda ito gamit ang tatlong tanong: Ano ang sinasabi? Ano ang ibig sabihin? Ano ang gagawin ko?"),
      t("Lead a 30-minute study this week and try to talk less than half the time.", "Pangunahan ang 30 minutong study ngayong linggo at subukang magsalita nang wala pang kalahati ng oras."),
      t("Ask your mentor or one group member for honest feedback afterward, and write down one thing to improve.", "Humingi ng tapat na feedback sa mentor mo o sa isang miyembro pagkatapos, at isulat ang isang bagay na pagbubutihin mo."),
    ],
    prayer: t(
      "Lord, Your Word is a lamp to my feet. Make me a worker who handles it correctly and humbly. Feed me first, so I can feed others. When I lead, open hearts the way You opened the Scriptures on the road to Emmaus. Keep me from showing off and help me make room for the quiet ones. Let the people I lead become like the Bereans, eager to search Your Word and quick to obey it. Amen.",
      "Panginoon, ang Salita Mo ay ilaw sa aking landas. Gawin Mo akong manggagawang gumagamit nito nang wasto at mapagpakumbaba. Pakainin Mo muna ako para mapakain ko ang iba. Kapag nangunguna ako, buksan Mo ang mga puso gaya ng pagbubukas Mo ng Kasulatan sa daan patungong Emmaus. Ilayo Mo ako sa pagyayabang at tulungan Mo akong magbigay ng puwang sa mga tahimik. Gawin Mong tulad ng mga taga-Berea ang mga inaakay ko, sabik na saliksikin ang Salita Mo at mabilis sumunod dito. Amen."
    ),
  },

  "praying-for-others": {
    revelation: t(
      "Before you ever speak to people about God, God invites you to speak to Him about people, and that is where lives truly begin to change.",
      "Bago mo pa makausap ang mga tao tungkol sa Diyos, inaanyayahan ka ng Diyos na kausapin Siya tungkol sa mga tao, at doon talaga nagsisimulang magbago ang buhay nila."
    ),
    mainTruth: t(
      "Paul urges that \"petitions, prayers, intercession and thanksgiving be made for all people,\" because God \"wants all people to be saved and to come to a knowledge of the truth\" (1 Timothy 2:1-4). For the Colossians he prayed without stopping that they would be filled with the knowledge of God's will, live worthy of the Lord, bear fruit, be strengthened with endurance and give joyful thanks (Colossians 1:9-12). James adds that we should pray for one another, \"for the prayer of a righteous person is powerful and effective\" (James 5:13-16). Intercession is standing between God and people, carrying them to the Father's throne.",
      "Hinihimok ni Pablo na \"gawin ang mga pagsamo, panalangin, pamamagitan at pasasalamat para sa lahat ng tao,\" dahil \"nais ng Diyos na maligtas ang lahat ng tao at makaalam ng katotohanan\" (1 Timoteo 2:1-4). Para sa mga taga-Colosas, walang tigil siyang nanalangin na mapuspos sila ng kaalaman sa kalooban ng Diyos, mamuhay nang karapat-dapat sa Panginoon, magbunga, palakasin sa pagtitiis at magpasalamat nang may galak (Colosas 1:9-12). Idinagdag ni Santiago na ipanalangin natin ang isa't isa, \"sapagkat makapangyarihan at mabisa ang panalangin ng taong matuwid\" (Santiago 5:13-16). Ang pamamagitan ay pagtayo sa pagitan ng Diyos at ng mga tao, dinadala sila sa trono ng Ama."
    ),
    insight: [
      t(
        "Look closely at Paul's prayer in Colossians 1. He does not pray for better health, a raise, or fewer problems, though those are fine to ask. He prays for knowledge of God's will, fruitfulness, endurance and joy. Most of our prayers for others are about removing their trouble. Paul's prayers were about growing their soul. A disciple maker learns to pray not only \"Lord, fix this\" but \"Lord, form Christ in them through this.\"",
        "Tingnang mabuti ang panalangin ni Pablo sa Colosas 1. Hindi siya nananalangin para sa mas mabuting kalusugan, dagdag-sahod o mas kaunting problema, kahit puwede namang hilingin ang mga iyon. Ipinapanalangin niya ang kaalaman sa kalooban ng Diyos, pagbubunga, pagtitiis at kagalakan. Karamihan sa panalangin natin para sa iba ay tungkol sa pag-aalis ng problema nila. Ang panalangin ni Pablo ay tungkol sa paglago ng kaluluwa nila. Natututo ang gumagawa ng alagad na manalangin hindi lang ng \"Panginoon, ayusin Mo ito\" kundi \"Panginoon, hubugin Mo si Cristo sa kanila sa pamamagitan nito.\""
      ),
      t(
        "We also forget that \"all people\" in 1 Timothy 2 includes \"kings and all those in authority,\" which in Paul's day meant pagan Roman rulers. Intercession is not only for the people we like. It is for the difficult boss, the employer who holds your passport, the official you did not vote for, and the relative who mocks your faith. Praying for them changes your heart toward them before it changes them.",
        "Nakakalimutan din natin na ang \"lahat ng tao\" sa 1 Timoteo 2 ay kasama ang \"mga hari at lahat ng may kapangyarihan,\" na noong panahon ni Pablo ay mga paganong pinuno ng Roma. Ang pamamagitan ay hindi lang para sa mga gusto natin. Para rin ito sa mahirap na amo, sa employer na may hawak ng pasaporte mo, sa opisyal na hindi mo ibinoto, at sa kamag-anak na nanunuya sa pananampalataya mo. Ang pananalangin para sa kanila ay nagbabago muna ng puso mo bago sila."
      ),
    ],
    life: [
      t(
        "A young man came to faith and later learned that an older sister in church had been praying for him by name every morning for six years, ever since she first saw him standing outside during a fellowship, too shy to enter. He never knew. When he finally heard, he wept and said, \"So that is why I could not run away from God.\" Behind many conversions is a hidden intercessor whose name no one mentions.",
        "May isang binatang lumapit kay Cristo, at nalaman niya pagkatapos na may isang ate sa simbahan na nananalangin para sa kanya, binabanggit ang pangalan niya tuwing umaga sa loob ng anim na taon, mula nang una siyang makita nitong nakatayo sa labas ng fellowship, nahihiyang pumasok. Hindi niya alam. Nang marinig niya ito, umiyak siya at nagsabi, \"Kaya pala hindi ako makatakas sa Diyos.\" Sa likod ng maraming pagbabalik-loob ay may nakatagong tagapamagitan na walang bumabanggit ng pangalan."
      ),
      t(
        "For an OFW, intercession may be the strongest thing you can do for family you cannot reach. You cannot fix your son's choices from Dubai or sit beside your sick mother in Pangasinan. But you can stand in the gap every night. Distance limits your hands; it does not limit your prayers. God is in both places at once.",
        "Para sa isang OFW, ang pamamagitan ang maaaring pinakamalakas na magagawa mo para sa pamilyang hindi mo maabot. Hindi mo maaayos ang mga desisyon ng anak mo mula Dubai o maupuan ang tabi ng maysakit mong nanay sa Pangasinan. Pero kaya mong tumayo sa puwang gabi-gabi. Nililimitahan ng layo ang mga kamay mo; hindi nito nililimitahan ang mga panalangin mo. Ang Diyos ay nasa dalawang lugar nang sabay."
      ),
    ],
    twist: t(
      "We often say, \"All I can do now is pray,\" as if prayer were the smallest thing. But in the Kingdom, prayer is not the last resort; it is the front line. Jesus Himself, risen and reigning, \"always lives to intercede\" for us (Hebrews 7:25). When you pray for others, you are not doing something small. You are joining the very ministry Jesus is doing right now at the Father's right hand.",
      "Madalas nating sabihin, \"Ang magagawa ko na lang ay manalangin,\" na parang ito ang pinakamaliit na bagay. Pero sa Kaharian, ang panalangin ay hindi huling paraan; ito ang unahan ng laban. Si Hesus mismo, buhay at naghahari, ay \"laging nabubuhay upang mamagitan\" para sa atin (Hebreo 7:25). Kapag ipinapanalangin mo ang iba, hindi maliit ang ginagawa mo. Nakikiisa ka sa mismong ministeryong ginagawa ni Hesus ngayon sa kanan ng Ama."
    ),
    confirm: [
      t("Exodus 32:11-14: Moses pleaded for Israel, and the Lord relented.", "Exodo 32:11-14: nagsumamo si Moises para sa Israel, at nagbago ang pasya ng Panginoon."),
      t("Luke 22:31-32: Jesus prayed for Peter that his faith would not fail.", "Lucas 22:31-32: ipinanalangin ni Hesus si Pedro na hindi manghina ang pananampalataya niya."),
      t("Ezekiel 22:30: God looked for someone to stand in the gap.", "Ezekiel 22:30: naghanap ang Diyos ng tatayo sa puwang."),
      t("Colossians 4:12: Epaphras was always wrestling in prayer for the believers.", "Colosas 4:12: si Epafras ay laging nakikipagbuno sa panalangin para sa mga mananampalataya."),
    ],
    heart: [
      t(
        "Move from praying only for your own needs to carrying others as your burden. Love that does not pray is thin love.",
        "Lumipat mula sa pananalangin para lang sa sariling pangangailangan tungo sa pagdadala sa iba bilang pasanin mo. Manipis ang pag-ibig na hindi nananalangin."
      ),
      t(
        "Let intercession soften your heart toward difficult people. You cannot keep praying for someone and keep hating them.",
        "Hayaang palambutin ng pamamagitan ang puso mo sa mga mahirap pakisamahan. Hindi mo kayang patuloy na ipanalangin ang isang tao habang patuloy mo siyang kinamumuhian."
      ),
    ],
    questions: [
      t("Who prayed faithfully for you, and how did it shape your life?", "Sino ang tapat na nanalangin para sa iyo, at paano nito hinubog ang buhay mo?"),
      t("Do your prayers for others focus more on their problems or on their growth in Christ?", "Mas nakatuon ba ang panalangin mo para sa iba sa problema nila o sa paglago nila kay Cristo?"),
      t("Is there someone in authority over you whom you have criticized more than prayed for?", "May tao bang may awtoridad sa iyo na mas pinupuna mo kaysa ipinapanalangin?"),
      t("What keeps you from praying regularly for the people you disciple?", "Ano ang pumipigil sa iyo na regular na ipanalangin ang mga dinidisciple mo?"),
    ],
    actions: [
      t("Write a prayer list of the people you disciple and those you hope to reach, and pray through it daily this week.", "Gumawa ng prayer list ng mga dinidisciple mo at ng mga gusto mong maabot, at ipanalangin ito araw-araw ngayong linggo."),
      t("Pray Colossians 1:9-12 word for word over three people, inserting their names.", "Ipanalangin ang Colosas 1:9-12 nang salita por salita para sa tatlong tao, isingit ang mga pangalan nila."),
      t("Message one person to tell them you prayed for them today, and ask how else you can pray.", "Mag-message sa isang tao para sabihing ipinanalangin mo siya ngayon, at itanong kung ano pa ang maipapanalangin mo."),
    ],
    prayer: t(
      "Father, thank You that Jesus is praying for me even now. Make me an intercessor who stands in the gap for others. Put names on my heart and keep them there. Teach me to pray not only for problems to disappear but for Christ to be formed in the people I love. Help me pray for those who are hard to love, and soften my heart as I do. Let my hidden prayers bear fruit I may never see. Amen.",
      "Ama, salamat dahil ipinapanalangin ako ni Hesus kahit ngayon. Gawin Mo akong tagapamagitang tumatayo sa puwang para sa iba. Ilagay Mo ang mga pangalan sa puso ko at panatilihin sila roon. Turuan Mo akong manalangin hindi lang para mawala ang mga problema kundi para mahubog si Cristo sa mga mahal ko. Tulungan Mo akong ipanalangin ang mga mahirap mahalin, at palambutin Mo ang puso ko habang ginagawa ko ito. Hayaan Mong magbunga ang mga lihim kong panalangin, kahit hindi ko na makita. Amen."
    ),
  },

  "caring-for-new-believers": {
    revelation: t(
      "New believers are not projects to fix but newborns to nurse, and God entrusts them to people who will be gentle like a mother and steady like a father.",
      "Ang mga bagong mananampalataya ay hindi proyektong aayusin kundi mga sanggol na aalagaan, at ipinagkakatiwala sila ng Diyos sa mga taong magiging malumanay gaya ng ina at matatag gaya ng ama."
    ),
    mainTruth: t(
      "Paul reminds the Thessalonians, \"we were like young children among you. Just as a nursing mother cares for her children, so we cared for you,\" sharing \"not only the gospel of God but our lives as well.\" Then he adds that he dealt with them \"as a father deals with his own children, encouraging, comforting and urging you to live lives worthy of God\" (1 Thessalonians 2:7-12). Peter tells new believers to crave \"pure spiritual milk\" so they may grow up in their salvation (1 Peter 2:1-3), and Hebrews reminds us that milk is meant to lead to solid food as believers mature through practice (Hebrews 5:12-14). New believers need tender care now, with the goal of strong faith later.",
      "Ipinaalala ni Pablo sa mga taga-Tesalonica, \"naging magiliw kami sa inyo, gaya ng inang nag-aalaga ng kanyang mga anak,\" ibinabahagi \"hindi lamang ang ebanghelyo ng Diyos kundi pati ang aming buhay.\" Idinagdag pa niya na tinrato niya sila \"gaya ng ama sa kanyang mga anak, pinapalakas ang loob, inaaliw at hinihimok na mamuhay nang karapat-dapat sa Diyos\" (1 Tesalonica 2:7-12). Sinabihan ni Pedro ang mga bagong mananampalataya na hangarin ang \"dalisay na gatas na espirituwal\" para lumago sila sa kaligtasan (1 Pedro 2:1-3), at ipinaalala ng Hebreo na ang gatas ay dapat humantong sa matigas na pagkain habang lumalago ang mananampalataya sa pagsasanay (Hebreo 5:12-14). Kailangan ng bagong mananampalataya ang malambing na pag-aalaga ngayon, na ang layunin ay matibay na pananampalataya balang araw."
    ),
    insight: [
      t(
        "Many churches celebrate when someone raises a hand at the altar, then leave that person alone the following week. But spiritual birth, like natural birth, is the beginning of care, not the end. No mother gives birth and then says, \"Good luck, baby, the fridge is over there.\" The first weeks are the most fragile. The enemy works hard to snatch the seed before it takes root (Mark 4:15). Follow-up is not an optional extra; it is protecting a newborn.",
        "Maraming simbahan ang nagdiriwang kapag may nagtaas ng kamay sa altar, tapos pinapabayaan na ang taong iyon sa sumunod na linggo. Pero ang espirituwal na kapanganakan, gaya ng natural na kapanganakan, ay simula ng pag-aalaga, hindi katapusan. Walang inang nanganak tapos nagsabing, \"Bahala ka na, anak, nandiyan ang ref.\" Ang unang mga linggo ang pinakamarupok. Masipag ang kaaway na agawin ang binhi bago ito mag-ugat (Marcos 4:15). Ang follow-up ay hindi dagdag lang; ito ay pagprotekta sa isang bagong silang."
      ),
      t(
        "Notice the balance in Paul: a mother's gentleness and a father's urging. Some of us are all mother: we comfort but never challenge, and the new believer stays a baby. Others are all father: we push standards and correct quickly, and the new believer feels crushed. Healthy care holds both. Gentle enough that they feel safe to fail, firm enough that they are called to grow.",
        "Pansinin ang balanse kay Pablo: kahinahunan ng ina at paghimok ng ama. Ang ilan sa atin ay puro ina: umaaliw pero hindi humahamon, kaya nananatiling sanggol ang bagong mananampalataya. Ang iba ay puro ama: nagpapataw ng pamantayan at mabilis magtuwid, kaya nadudurog ang bagong mananampalataya. Ang malusog na pag-aalaga ay may dalawa. Sapat na malumanay para maramdaman nilang ligtas silang magkamali, sapat na matatag para tawagin silang lumago."
      ),
    ],
    life: [
      t(
        "Marco accepted Christ at a company Christmas party in Qatar. The next Monday, Kuya Dennis messaged him: \"Kumusta ka na, bro? Can I buy you coffee after shift?\" Every week for three months they met, read a short passage, and Dennis answered questions like \"Can I still drink?\" and \"What if I fall again?\" without shock or lecture. When Marco slipped back into gambling one payday, Dennis did not disappear. He came over, prayed with him, and helped him set up a remittance so the money went home first. Marco says today, \"I did not stay because I was strong. I stayed because someone stayed with me.\"",
        "Tinanggap ni Marco si Cristo sa Christmas party ng kompanya nila sa Qatar. Noong sumunod na Lunes, nag-message si Kuya Dennis: \"Kumusta ka na, bro? Libre kita ng kape pagkatapos ng shift?\" Bawat linggo sa loob ng tatlong buwan, nagkikita sila, nagbabasa ng maikling talata, at sinasagot ni Dennis ang mga tanong gaya ng \"Puwede pa ba akong uminom?\" at \"Paano kung madapa ulit ako?\" nang hindi nagugulat o nagsesermon. Nang bumalik si Marco sa sugal isang sweldo, hindi nawala si Dennis. Pinuntahan niya ito, ipinanalangin, at tinulungang mag-set up ng remittance para unang mapunta ang pera sa pamilya. Sabi ni Marco ngayon, \"Hindi ako nanatili dahil malakas ako. Nanatili ako dahil may taong nanatili sa akin.\""
      ),
      t(
        "Think of how a Filipino family welcomes a newborn: everyone takes turns, Lola gives advice, Tita brings gifts, Kuya carries the baby. A new believer needs a church family like that, not one assigned volunteer. Introduce them to a small group, invite them to your home, sit with them in service. Belonging often comes before full believing and steady behaving.",
        "Isipin kung paano sinasalubong ng pamilyang Pinoy ang isang bagong silang: nagpapalitan ang lahat, nagpapayo si Lola, may regalo si Tita, kinakarga ni Kuya ang sanggol. Kailangan ng bagong mananampalataya ang ganyang pamilya sa simbahan, hindi isang volunteer lang na naka-assign. Ipakilala siya sa small group, imbitahan sa bahay mo, tabihan sa service. Madalas, nauuna ang pakiramdam ng pagiging kabilang bago ang buong paniniwala at matatag na pamumuhay."
      ),
    ],
    twist: t(
      "We think caring for new believers is mostly about teaching them correct doctrine. But Paul said he shared \"our lives as well,\" because they had become \"so dear\" to him (1 Thessalonians 2:8). The twist is that new believers learn God's love first through the warmth of God's people. The doctrine of grace becomes believable when they experience grace from you on the day they fail.",
      "Akala natin ang pag-aalaga sa bagong mananampalataya ay pangunahing pagtuturo ng tamang doktrina. Pero sabi ni Pablo, ibinahagi niya \"pati ang aming buhay,\" dahil naging \"napakamahal\" nila sa kanya (1 Tesalonica 2:8). Ang twist: unang natututunan ng bagong mananampalataya ang pag-ibig ng Diyos sa init ng bayan ng Diyos. Nagiging kapani-paniwala ang doktrina ng biyaya kapag naranasan nila ang biyaya mula sa iyo sa araw na madapa sila."
    ),
    confirm: [
      t("Acts 9:26-28: Barnabas took the new convert Saul and brought him to the apostles.", "Gawa 9:26-28: kinuha ni Bernabe ang bagong mananampalatayang si Saulo at dinala sa mga apostol."),
      t("Isaiah 40:11: He gathers the lambs in His arms and gently leads those with young.", "Isaias 40:11: tinitipon Niya ang mga kordero sa Kanyang bisig at marahang inaakay ang mga may anak."),
      t("Acts 2:42: the new believers devoted themselves to teaching, fellowship, meals and prayer.", "Gawa 2:42: inilaan ng mga bagong mananampalataya ang sarili sa turo, pagsasama, pagkain at panalangin."),
      t("Romans 15:7: accept one another as Christ accepted you.", "Roma 15:7: tanggapin ang isa't isa gaya ng pagtanggap sa inyo ni Cristo."),
    ],
    heart: [
      t(
        "Move from being shocked by new believers' struggles to being patient with them. You were once a baby too, and God was patient with you.",
        "Lumipat mula sa pagkagulat sa mga pinagdadaanan ng bagong mananampalataya tungo sa pagiging matiyaga sa kanila. Naging sanggol ka rin noon, at matiyaga sa iyo ang Diyos."
      ),
      t(
        "Let your care be warm and your hope be high. Love them as they are, and believe for who God is making them to be.",
        "Gawing mainit ang pag-aalaga mo at mataas ang pag-asa mo. Mahalin sila kung ano sila, at manampalataya para sa kung sino ang hinuhubog ng Diyos sa kanila."
      ),
    ],
    questions: [
      t("What did you need most in your first months as a believer, and who gave it to you?", "Ano ang pinakakailangan mo sa unang mga buwan mo bilang mananampalataya, at sino ang nagbigay nito?"),
      t("Are you more like the mother or the father in Paul's picture? Which side do you need to grow in?", "Mas kahawig ka ba ng ina o ng ama sa larawan ni Pablo? Saang panig ka kailangang lumago?"),
      t("How do you usually react when a new believer falls back into old sin?", "Paano ka karaniwang tumutugon kapag bumalik sa dating kasalanan ang isang bagong mananampalataya?"),
      t("Who is new in your church or workplace fellowship whom no one is following up?", "Sino ang bago sa simbahan o fellowship sa trabaho ninyo na walang kumukumusta?"),
    ],
    actions: [
      t("Contact one new believer within the next three days, ask how they are, and offer to meet.", "Kontakin ang isang bagong mananampalataya sa loob ng tatlong araw, kumustahin siya, at alukin ng pagkikita."),
      t("Walk them through one Level 1 lesson of this journey together this week.", "Sabay ninyong pag-aralan ang isang lesson sa Level 1 ng journey na ito ngayong linggo."),
      t("Introduce them personally to at least two other believers or a small group.", "Ipakilala siya nang personal sa hindi bababa sa dalawang ibang mananampalataya o sa isang small group."),
    ],
    prayer: t(
      "Gentle Shepherd, You carry the lambs close to Your heart. Give me that same heart for new believers. Make me gentle like a mother and steady like a father. Keep me from being shocked by their struggles or impatient with their questions. Help me share not only Your Word but my life. Protect every new seed from being snatched away, and let them grow from milk to solid food, rooted in You. Amen.",
      "Mahinahong Pastol, dinadala Mo ang mga kordero malapit sa Iyong puso. Bigyan Mo ako ng ganoong puso para sa mga bagong mananampalataya. Gawin Mo akong malumanay gaya ng ina at matatag gaya ng ama. Ilayo Mo ako sa pagkagulat sa mga pinagdadaanan nila o pagkainip sa mga tanong nila. Tulungan Mo akong ibahagi hindi lang ang Salita Mo kundi pati ang buhay ko. Ingatan Mo ang bawat bagong binhi na hindi maagaw, at palaguin Mo sila mula gatas hanggang matigas na pagkain, nakaugat sa Iyo. Amen."
    ),
  },

  "multiplying-disciples": {
    revelation: t(
      "God did not call you to collect followers but to raise up people who will raise up others, because the Great Commission is measured in generations, not in crowds.",
      "Hindi ka tinawag ng Diyos na mangolekta ng tagasunod kundi magpalaki ng mga taong magpapalaki rin ng iba, dahil ang Dakilang Utos ay sinusukat sa mga henerasyon, hindi sa dami ng tao."
    ),
    mainTruth: t(
      "Paul tells Timothy, \"Be strong in the grace that is in Christ Jesus. And the things you have heard me say in the presence of many witnesses entrust to reliable people who will also be qualified to teach others\" (2 Timothy 2:1-2). That one verse holds four generations: Paul, Timothy, reliable people, and others. In Ephesus Paul taught daily in the lecture hall of Tyrannus for two years, \"so that all the Jews and Greeks who lived in the province of Asia heard the word of the Lord\" (Acts 19:8-10), not because Paul visited every town, but because the people he trained went out. His aim was to \"present everyone fully mature in Christ,\" and he labored for it with all the energy Christ powerfully worked in him (Colossians 1:28-29).",
      "Sabi ni Pablo kay Timoteo, \"Magpakatatag ka sa biyayang na kay Cristo Hesus. Ang mga narinig mo sa akin sa harap ng maraming saksi ay ipagkatiwala mo sa mga taong tapat na may kakayahan ding magturo sa iba\" (2 Timoteo 2:1-2). Apat na henerasyon ang nasa iisang talatang iyan: si Pablo, si Timoteo, mga taong tapat, at iba pa. Sa Efeso, araw-araw na nagturo si Pablo sa bulwagan ni Tyrannus sa loob ng dalawang taon, \"kaya't narinig ng lahat ng Judio at Griego na nakatira sa lalawigan ng Asia ang salita ng Panginoon\" (Gawa 19:8-10), hindi dahil binisita ni Pablo ang bawat bayan, kundi dahil humayo ang mga sinanay niya. Ang layunin niya ay \"iharap ang bawat tao na ganap kay Cristo,\" at nagpagal siya para rito sa lakas na kumikilos nang makapangyarihan sa kanya (Colosas 1:28-29)."
    ),
    insight: [
      t(
        "Many faithful believers think the goal is to be a good disciple. That is the start, but Jesus said, \"Go and make disciples.\" A Christian who keeps growing but never passes it on is like a mango tree whose fruit falls and rots under it. The fruit was meant to carry seeds. Your walk with God is not only for your benefit; it is meant to be reproduced in someone else, who will reproduce it in someone else.",
        "Maraming tapat na mananampalataya ang nag-iisip na ang layunin ay maging mabuting alagad. Simula iyon, pero sabi ni Hesus, \"Humayo kayo at gumawa ng mga alagad.\" Ang Kristiyanong patuloy na lumalago pero hindi kailanman nagpapasa ay parang punong mangga na ang bunga ay nahuhulog at nabubulok sa ilalim nito. Ang bunga ay ginawa para magdala ng binhi. Ang lakad mo kasama ang Diyos ay hindi lang para sa iyo; ginawa ito para magparami sa iba, na magpaparami rin sa iba."
      ),
      t(
        "Notice Paul's word \"reliable\" or \"faithful.\" He did not tell Timothy to find the most talented or popular. Multiplication depends less on charisma and more on faithfulness: people who show up, obey what they learn and pass it on. Also notice that Paul begins with \"be strong in grace.\" Multiplication that runs on guilt or ambition burns out. Multiplication that runs on grace keeps going.",
        "Pansinin ang salita ni Pablo na \"tapat.\" Hindi niya sinabihan si Timoteo na hanapin ang pinakamagaling o pinakasikat. Ang pagpaparami ay mas nakasalalay sa katapatan kaysa sa karisma: mga taong dumarating, sumusunod sa natututunan nila at nagpapasa nito. Pansinin din na nagsimula si Pablo sa \"magpakatatag sa biyaya.\" Ang pagpaparaming pinapatakbo ng konsensya o ambisyon ay nauupos. Ang pagpaparaming pinapatakbo ng biyaya ay nagpapatuloy."
      ),
    ],
    life: [
      t(
        "Imagine two people. One preaches to a thousand new people every day. The other disciples just one person a year, and each year both of them disciple one more, and so on. After a few years, the preacher seems far ahead. But because the second keeps doubling, in about thirty years the disciples would outnumber the whole world. It is a simple picture, but it shows why Jesus invested so deeply in twelve. Depth that multiplies always outruns breadth that does not.",
        "Isipin ang dalawang tao. Ang isa ay nangangaral sa isang libong bagong tao araw-araw. Ang isa naman ay nagdidisciple ng isang tao lang bawat taon, at bawat taon, pareho silang nagdidisciple ng isa pa, at ganoon din ang susunod. Pagkalipas ng ilang taon, mukhang mas malayo ang narating ng mangangaral. Pero dahil patuloy na dumodoble ang ikalawa, sa loob ng mga tatlumpung taon, mas marami na ang mga alagad kaysa sa buong mundo. Simpleng larawan ito, pero ipinapakita nito kung bakit lubos na namuhunan si Hesus sa labindalawa. Ang lalim na nagpaparami ay laging nauuna sa lawak na hindi nagpaparami."
      ),
      t(
        "In many Middle East camps, there is no pastor and no church building. Yet the gospel spreads because a nurse disciples a fellow nurse, who starts a study in her villa, whose members bring it to the next compound. When contracts end and people go home to the province or move to another country, the faith goes with them. God scatters OFWs, and wise disciple makers make sure that what is scattered is seed.",
        "Sa maraming kampo sa Middle East, walang pastor at walang gusali ng simbahan. Pero kumakalat ang ebanghelyo dahil may nurse na nagdidisciple ng kapwa nurse, na nagsimula ng study sa villa niya, at dinala ito ng mga miyembro sa kabilang compound. Kapag natapos ang kontrata at umuwi sila sa probinsya o lumipat sa ibang bansa, kasama nilang dala ang pananampalataya. Ikinakalat ng Diyos ang mga OFW, at tinitiyak ng matatalinong gumagawa ng alagad na binhi ang ikinakalat."
      ),
    ],
    twist: t(
      "We measure ministry by how many people listen to us. But Jesus left earth with about one hundred twenty followers in an upper room, and it was enough to turn the world upside down. The twist: the best sign of your fruitfulness is not how much people need you, but how well they can go on without you. A disciple maker succeeds when his disciples' disciples are making disciples, and his own name is forgotten.",
      "Sinusukat natin ang ministeryo sa dami ng nakikinig sa atin. Pero umalis si Hesus sa mundo na may mga isang daan at dalawampung tagasunod sa isang silid sa itaas, at sapat iyon para baligtarin ang mundo. Ang twist: ang pinakamagandang tanda ng pagiging mabunga mo ay hindi kung gaano ka kailangan ng mga tao, kundi kung gaano sila makapagpapatuloy kahit wala ka. Nagtatagumpay ang gumagawa ng alagad kapag ang mga alagad ng mga alagad niya ay gumagawa na ng alagad, at nakalimutan na ang pangalan niya."
    ),
    confirm: [
      t("Matthew 28:18-20: all authority is His; therefore make disciples of all nations.", "Mateo 28:18-20: nasa Kanya ang lahat ng kapangyarihan; kaya gumawa ng alagad sa lahat ng bansa."),
      t("John 15:8: the Father is glorified when we bear much fruit.", "Juan 15:8: naluluwalhati ang Ama kapag namumunga tayo nang sagana."),
      t("Acts 8:4: those scattered by persecution preached the word wherever they went.", "Gawa 8:4: ang mga nangalat dahil sa pag-uusig ay nangaral ng salita saanman sila magpunta."),
      t("1 Thessalonians 1:6-8: the Thessalonians imitated Paul, and the message rang out from them everywhere.", "1 Tesalonica 1:6-8: tinularan ng mga taga-Tesalonica si Pablo, at umalingawngaw mula sa kanila ang salita sa lahat ng dako."),
    ],
    heart: [
      t(
        "Move from being a consumer of teaching to being a carrier of it. Everything you receive, receive with someone else in mind.",
        "Lumipat mula sa pagiging tagatanggap ng turo tungo sa pagiging tagadala nito. Lahat ng natatanggap mo, tanggapin mo na may ibang taong nasa isip."
      ),
      t(
        "Let go of the need to be needed. Rejoice when the people you trained go further than you.",
        "Bitawan ang pangangailangang kailanganin. Magalak kapag mas malayo ang narating ng mga sinanay mo kaysa sa iyo."
      ),
    ],
    questions: [
      t("Who discipled you, and whom have you passed it on to?", "Sino ang nagdisciple sa iyo, at kanino mo ito naipasa?"),
      t("If you disappeared for a year, would the people you lead keep growing and leading others?", "Kung mawala ka nang isang taon, patuloy bang lalago at mangunguna sa iba ang mga inaakay mo?"),
      t("Who in your circle is faithful, available and teachable, even if not yet impressive?", "Sino sa paligid mo ang tapat, available at handang matuto, kahit hindi pa kahanga-hanga?"),
      t("Is your ministry running on grace, or on guilt and ambition?", "Biyaya ba ang nagpapatakbo sa ministeryo mo, o konsensya at ambisyon?"),
    ],
    actions: [
      t("Draw your discipleship \"family tree\": who discipled you, whom you disciple, and whom they disciple.", "Iguhit ang \"family tree\" ng discipleship mo: sino ang nagdisciple sa iyo, sino ang dinidisciple mo, at sino ang dinidisciple nila."),
      t("Ask one person you disciple, \"Whom could you share this with?\" and help them start.", "Tanungin ang isang dinidisciple mo, \"Kanino mo puwedeng ibahagi ito?\" at tulungan siyang magsimula."),
      t("Next time you teach, let your disciple lead part of it while you coach afterward.", "Sa susunod na magtuturo ka, hayaang pangunahan ng disipulo mo ang bahagi nito, at saka mo siya i-coach pagkatapos."),
    ],
    prayer: t(
      "Lord of the harvest, You commanded us to make disciples of all nations. Forgive me for keeping what You gave me to myself. Strengthen me in Your grace, not in my pride. Show me faithful people to entrust Your truth to, and help me train them to train others. Let what You started in me reach generations I will never meet. Scatter Your people like seed, and let the fruit glorify only You. Amen.",
      "Panginoon ng anihan, iniutos Mo sa amin na gumawa ng alagad sa lahat ng bansa. Patawarin Mo ako sa pagsasarili ng ibinigay Mo sa akin. Palakasin Mo ako sa Iyong biyaya, hindi sa aking pagmamataas. Ipakita Mo ang mga taong tapat na mapagkakatiwalaan ng Iyong katotohanan, at tulungan Mo akong sanayin sila para magsanay rin ng iba. Hayaan Mong ang sinimulan Mo sa akin ay umabot sa mga henerasyong hindi ko na makikilala. Ikalat Mo ang Iyong bayan gaya ng binhi, at hayaang ang bunga ay magluwalhati sa Iyo lamang. Amen."
    ),
  },

  "asking-questions-like-jesus": {
    revelation: t(
      "Jesus often changed people not by giving answers but by asking questions that made them face the truth for themselves.",
      "Madalas binabago ni Hesus ang mga tao hindi sa pagbibigay ng sagot kundi sa pagtatanong na nagtutulak sa kanilang harapin mismo ang katotohanan."
    ),
    mainTruth: t(
      "At Caesarea Philippi Jesus asked, \"Who do people say I am?\" and then, \"But what about you? Who do you say I am?\" and Peter confessed, \"You are the Messiah\" (Mark 8:27-30). When an expert in the law tested Him, Jesus answered with questions: \"What is written in the Law?\" and after the story of the Samaritan, \"Which of these three was a neighbor?\" (Luke 10:25-37). After Peter's denial, the risen Jesus restored him with one question asked three times: \"Do you love Me?\" (John 21:15-17). Jesus' questions invited confession, exposed hearts and healed wounds.",
      "Sa Cesarea ni Felipe, nagtanong si Hesus, \"Sino raw Ako ayon sa mga tao?\" at saka, \"Kayo naman, sino Ako para sa inyo?\" at ipinahayag ni Pedro, \"Ikaw ang Cristo\" (Marcos 8:27-30). Nang subukin Siya ng isang dalubhasa sa kautusan, sinagot Siya ni Hesus ng mga tanong: \"Ano ang nakasulat sa Kautusan?\" at pagkatapos ng kuwento ng Samaritano, \"Sino sa tatlo ang naging kapwa?\" (Lucas 10:25-37). Pagkatapos ng pagtatwa ni Pedro, ibinalik siya ng nabuhay na Hesus sa isang tanong na tatlong beses: \"Mahal mo ba Ako?\" (Juan 21:15-17). Ang mga tanong ni Hesus ay nag-anyaya ng pagpapahayag, naglantad ng puso at nagpagaling ng sugat."
    ),
    insight: [
      t(
        "Jesus knew everything, yet He asked many questions in the Gospels. He did not ask because He lacked information; He asked because people needed to discover what was in their own hearts. Truth that someone discovers becomes their own. Truth that is only told to them often stays outside. When we rush to give answers, we may rob people of the moment when the Spirit was about to speak to them directly.",
        "Alam ni Hesus ang lahat, pero napakaraming tanong ang itinanong Niya sa mga Ebanghelyo. Hindi Siya nagtanong dahil kulang Siya sa impormasyon; nagtanong Siya dahil kailangang matuklasan ng tao kung ano ang nasa sarili nilang puso. Ang katotohanang natuklasan ng isang tao ay nagiging kanya. Ang katotohanang ipinagsabi lang sa kanya ay madalas nananatili sa labas. Kapag nagmamadali tayong magbigay ng sagot, baka naagawan natin ang tao ng sandaling magsasalita na sana sa kanila nang direkta ang Espiritu."
      ),
      t(
        "Notice how Jesus turned the lawyer's question around. The man asked, \"Who is my neighbor?\" meaning, \"Whom do I have to love?\" Jesus ended with, \"Which one acted like a neighbor?\" meaning, \"What kind of person will you be?\" A good question does not just collect information; it shifts the focus from theory to the heart. Disciple makers learn to ask questions that move people from debate to decision.",
        "Pansinin kung paano binaligtad ni Hesus ang tanong ng abogado. Tanong ng lalaki, \"Sino ang aking kapwa?\" ibig sabihin, \"Sino lang ang kailangan kong mahalin?\" Tinapos ni Hesus sa, \"Sino ang kumilos bilang kapwa?\" ibig sabihin, \"Anong klaseng tao ka magiging?\" Ang mahusay na tanong ay hindi lang nangongolekta ng impormasyon; inililipat nito ang pokus mula teorya tungo sa puso. Natututo ang gumagawa ng alagad na magtanong na naglilipat sa tao mula sa debate tungo sa desisyon."
      ),
    ],
    life: [
      t(
        "Ate Liza used to answer every problem her disciple brought: \"Just pray more,\" \"Just forgive him,\" \"Just tithe.\" Her disciple nodded and changed nothing. After learning from Jesus, she tried something different. When the young woman complained again about her husband back home, Liza asked, \"What do you think God is showing you about your own heart in this?\" The silence was long. Then came tears and a real confession. One honest question did more than a year of advice.",
        "Dati, sinasagot ni Ate Liza ang bawat problemang dinadala ng disipulo niya: \"Mag-pray ka lang nang mas marami,\" \"Patawarin mo na lang siya,\" \"Mag-tithe ka lang.\" Tumatango ang disipulo pero walang nagbabago. Nang matuto siya kay Hesus, iba ang sinubukan niya. Nang muling magreklamo ang dalaga tungkol sa asawa niya sa Pilipinas, nagtanong si Liza, \"Ano sa tingin mo ang ipinapakita ng Diyos tungkol sa sarili mong puso rito?\" Matagal ang katahimikan. Tapos dumating ang luha at tunay na pag-amin. Ang isang tapat na tanong ay nakagawa nang higit sa isang taon ng payo."
      ),
      t(
        "Filipinos are polite. Ask, \"Okay ka lang?\" and the answer is almost always, \"Okay lang.\" Closed questions get polite answers. Open questions get honest ones: \"What was the hardest part of your week?\" \"Where did you sense God today?\" \"What is one thing you would change if you could?\" Learn to ask, then wait. Silence is not your enemy; it is often the Spirit at work.",
        "Magalang ang mga Pinoy. Itanong mo, \"Okay ka lang?\" at halos laging ang sagot, \"Okay lang.\" Ang saradong tanong ay may magalang na sagot. Ang bukas na tanong ay may tapat na sagot: \"Ano ang pinakamahirap na bahagi ng linggo mo?\" \"Saan mo naramdaman ang Diyos ngayong araw?\" \"Ano ang isang bagay na babaguhin mo kung kaya mo?\" Matutong magtanong, saka maghintay. Hindi kaaway ang katahimikan; madalas, ang Espiritu iyon na kumikilos."
      ),
    ],
    twist: t(
      "We think asking questions shows weakness, that a real leader should always have the answer. But the One who is the Answer asked the most questions. The twist: when you ask good questions, you are not giving up authority; you are making room for a greater Authority, the Holy Spirit, to speak. And sometimes the most important question is the one Jesus keeps asking you: \"Do you love Me?\" Disciple makers who answer that question honestly ask better questions of others.",
      "Akala natin kahinaan ang pagtatanong, na ang tunay na leader ay dapat laging may sagot. Pero ang Siyang Sagot mismo ang pinakamaraming nagtanong. Ang twist: kapag nagtatanong ka ng mahusay na tanong, hindi mo isinusuko ang awtoridad; nagbibigay ka ng puwang para magsalita ang mas dakilang Awtoridad, ang Banal na Espiritu. At minsan, ang pinakamahalagang tanong ay ang patuloy na itinatanong sa iyo ni Hesus: \"Mahal mo ba Ako?\" Ang gumagawa ng alagad na tapat na sumasagot sa tanong na iyan ay nagtatanong ng mas mahusay na tanong sa iba."
    ),
    confirm: [
      t("Genesis 3:9: God's first question to fallen man: \"Where are you?\"", "Genesis 3:9: ang unang tanong ng Diyos sa nagkasalang tao: \"Nasaan ka?\""),
      t("Luke 24:17: the risen Jesus asked the sad disciples, \"What are you discussing?\"", "Lucas 24:17: tinanong ng nabuhay na Hesus ang malungkot na mga alagad, \"Ano ang pinag-uusapan ninyo?\""),
      t("Proverbs 20:5: the purposes of a heart are deep waters; a person of understanding draws them out.", "Kawikaan 20:5: malalim na tubig ang layunin ng puso; inaahon ito ng taong may unawa."),
      t("James 1:19: be quick to listen, slow to speak.", "Santiago 1:19: maging mabilis sa pakikinig, mabagal sa pagsasalita."),
    ],
    heart: [
      t(
        "Move from needing to be the expert to wanting the other person to meet God. Curiosity is a form of love.",
        "Lumipat mula sa pangangailangang maging eksperto tungo sa pagnanais na makatagpo ng kausap mo ang Diyos. Ang tunay na pag-uusisa ay isang anyo ng pag-ibig."
      ),
      t(
        "Learn to listen with your whole heart. People open up to those who make them feel heard, not judged.",
        "Matutong makinig nang buong puso. Nagbubukas ang mga tao sa mga nagpaparamdam na pinapakinggan sila, hindi hinuhusgahan."
      ),
    ],
    questions: [
      t("Which question of Jesus speaks most directly to you right now, and why?", "Aling tanong ni Hesus ang pinakatumatama sa iyo ngayon, at bakit?"),
      t("When someone shares a problem, do you usually tell or ask first?", "Kapag may nagbabahagi ng problema, karaniwan ka bang nagsasabi o nagtatanong muna?"),
      t("How comfortable are you with silence after asking a question?", "Gaano ka komportable sa katahimikan pagkatapos magtanong?"),
      t("If Jesus asked you today, \"Do you love Me?\", how would you honestly answer?", "Kung tanungin ka ni Hesus ngayon, \"Mahal mo ba Ako?\", paano ka tapat na sasagot?"),
    ],
    actions: [
      t("Write down five open questions you can use with the people you disciple.", "Isulat ang limang bukas na tanong na magagamit mo sa mga dinidisciple mo."),
      t("In your next meeting, ask at least five questions and talk less than half the time.", "Sa susunod mong pakikipagkita, magtanong ng hindi bababa sa lima at magsalita nang wala pang kalahati ng oras."),
      t("Spend ten minutes alone letting Jesus ask you, \"Do you love Me?\" and write your answer to Him.", "Maglaan ng sampung minuto nang mag-isa, hayaang tanungin ka ni Hesus, \"Mahal mo ba Ako?\" at isulat ang sagot mo sa Kanya."),
    ],
    prayer: t(
      "Lord Jesus, You asked Peter three times, \"Do you love Me?\" and healed his heart. Ask me too, and help me answer honestly. Teach me to ask questions the way You did: with love, with patience, and with room for Your Spirit to speak. Silence my need to be right and to have every answer. Give me ears that truly listen, so the people I walk with can discover You for themselves. Amen.",
      "Panginoong Hesus, tatlong beses Mong tinanong si Pedro, \"Mahal mo ba Ako?\" at pinagaling Mo ang puso niya. Tanungin Mo rin ako, at tulungan Mo akong sumagot nang tapat. Turuan Mo akong magtanong gaya Mo: may pag-ibig, may tiyaga, at may puwang para magsalita ang Iyong Espiritu. Patahimikin Mo ang pangangailangan kong laging tama at laging may sagot. Bigyan Mo ako ng taingang tunay na nakikinig, para matuklasan Ka mismo ng mga kasama ko. Amen."
    ),
  },

  "telling-your-story": {
    revelation: t(
      "You do not need to win every argument about Jesus; you only need to tell honestly what He has done for you, and no one can take that away.",
      "Hindi mo kailangang manalo sa bawat pagtatalo tungkol kay Hesus; kailangan mo lang ikuwento nang tapat ang ginawa Niya sa iyo, at walang makaaagaw niyon."
    ),
    mainTruth: t(
      "The religious leaders pressured the man born blind, insisting that Jesus was a sinner. He did not have a theology degree, but he had a testimony: \"One thing I do know. I was blind but now I see!\" (John 9:24-34). They threw him out, but they could not refute him. John begins his letter the same way: \"That which we have heard, which we have seen with our eyes, which we have looked at and our hands have touched... we proclaim to you,\" so that others may share fellowship with the Father and the Son and our joy may be complete (1 John 1:1-4). A testimony is eyewitness evidence of a living Savior.",
      "Pinilit ng mga pinunong panrelihiyon ang lalaking ipinanganak na bulag, iginigiit na makasalanan si Hesus. Wala siyang diploma sa teolohiya, pero may patotoo siya: \"Isang bagay ang alam ko. Ako'y bulag noon, pero ngayon ay nakakakita na!\" (Juan 9:24-34). Pinalayas nila siya, pero hindi nila siya nasagot. Ganito rin sinimulan ni Juan ang sulat niya: \"Ang aming narinig, ang aming nakita ng aming mga mata, ang aming pinagmasdan at nahawakan ng aming mga kamay... ito ang ipinapahayag namin sa inyo,\" para makibahagi rin ang iba sa pakikisama sa Ama at sa Anak at malubos ang aming kagalakan (1 Juan 1:1-4). Ang patotoo ay ebidensya ng saksi sa isang buhay na Tagapagligtas."
    ),
    insight: [
      t(
        "Many believers stay silent because they think they need to know all the answers first. The blind man openly said, \"Whether He is a sinner or not, I don't know.\" He admitted what he did not know and stood firm on what he did. That is the power of testimony. You may not be able to explain the Trinity to your coworker, but you can say, \"I used to be angry all the time, and Jesus changed that.\" No one is an expert on your life except you and God.",
        "Maraming mananampalataya ang nananahimik dahil akala nila kailangan muna nilang malaman ang lahat ng sagot. Inamin ng bulag, \"Kung makasalanan Siya o hindi, hindi ko alam.\" Inamin niya ang hindi niya alam at tumayo nang matatag sa alam niya. Iyan ang kapangyarihan ng patotoo. Baka hindi mo maipaliwanag ang Trinidad sa katrabaho mo, pero kaya mong sabihin, \"Dati laging mainit ang ulo ko, at binago iyon ni Hesus.\" Walang eksperto sa buhay mo kundi ikaw at ang Diyos."
      ),
      t(
        "Notice also the goal of John's testimony: fellowship and joy, not winning. A good story points away from yourself to Jesus. Many testimonies spend ten minutes on how bad life was and thirty seconds on Christ. Others make the speaker sound like a hero. A Spirit-led testimony is honest about the past, clear about Jesus, and real about the present, including the struggles you still bring to Him.",
        "Pansinin din ang layunin ng patotoo ni Juan: pakikisama at kagalakan, hindi panalo. Ang mahusay na kuwento ay tumuturo palayo sa sarili mo patungo kay Hesus. Maraming patotoo ang sampung minuto sa kung gaano kasama ang buhay at tatlumpung segundo lang kay Cristo. Ang iba naman ay ginagawang bida ang nagsasalita. Ang patotoong pinangungunahan ng Espiritu ay tapat tungkol sa nakaraan, malinaw tungkol kay Hesus, at totoo tungkol sa kasalukuyan, pati ang mga pinagdadaanan mong dinadala mo pa sa Kanya."
      ),
    ],
    life: [
      t(
        "On a long bus ride from Abu Dhabi, Tess sat beside a Filipina who was crying quietly after a call with her family. Tess did not open with a sermon. She said, \"Two years ago I was crying on this same route. My marriage was breaking and I thought of ending my life. Someone told me about Jesus, and He gave me peace I cannot explain.\" Three minutes, plain words. The woman asked, \"Can you pray for me?\" A short, honest story opened a door that an argument never could.",
        "Sa mahabang biyahe ng bus mula Abu Dhabi, katabi ni Tess ang isang Pinay na tahimik na umiiyak pagkatapos ng tawag sa pamilya. Hindi nagsimula si Tess sa sermon. Sabi niya, \"Dalawang taon na ang nakaraan, umiiyak din ako sa rutang ito. Nasisira ang kasal ko at naisip kong tapusin na ang buhay ko. May nagkuwento sa akin tungkol kay Hesus, at binigyan Niya ako ng kapayapaang hindi ko maipaliwanag.\" Tatlong minuto, payak na salita. Nagtanong ang babae, \"Puwede mo ba akong ipanalangin?\" Isang maikli at tapat na kuwento ang nagbukas ng pintong hindi kailanman mabubuksan ng pagtatalo."
      ),
      t(
        "A simple shape helps: before Jesus (what my life was like), meeting Jesus (how I came to trust Him), and since Jesus (what is different now). Keep it short enough to tell during a merienda break, about three minutes. Use everyday words, not church words like \"sanctified\" or \"washed in the blood\" that outsiders may not understand. Practice it until it flows like a story you would tell at a family reunion.",
        "Makakatulong ang simpleng hugis: bago si Hesus (ano ang buhay ko noon), pagkakilala kay Hesus (paano ako nagtiwala sa Kanya), at mula nang makilala si Hesus (ano ang naiba ngayon). Gawin itong sapat na maikli para maikuwento sa merienda break, mga tatlong minuto. Gumamit ng pang-araw-araw na salita, hindi salitang pang-simbahan gaya ng \"sanctified\" o \"nahugasan ng dugo\" na baka hindi maunawaan ng hindi pa mananampalataya. Sanayin ito hanggang dumaloy na parang kuwentong ikukuwento mo sa reunion ng pamilya."
      ),
    ],
    twist: t(
      "We think we need a dramatic testimony, like being rescued from drugs or prison, for our story to matter. But the blind man's power was not drama; it was certainty: \"I was blind, now I see.\" The twist: being kept from a destructive life is as much a miracle as being rescued from one. If you grew up in church and Jesus guarded you from many wrong turns, that is a testimony of grace too. Every story in which Jesus is the hero is worth telling.",
      "Akala natin kailangan ng dramatikong patotoo, gaya ng pagkaligtas mula sa droga o bilangguan, para mahalaga ang kuwento natin. Pero ang kapangyarihan ng bulag ay hindi drama; ito ay katiyakan: \"Bulag ako noon, nakakakita na ngayon.\" Ang twist: ang maingatan mula sa mapanirang buhay ay himala rin gaya ng maligtas mula rito. Kung lumaki ka sa simbahan at iningatan ka ni Hesus sa maraming maling liko, patotoo rin iyon ng biyaya. Bawat kuwento kung saan si Hesus ang bida ay karapat-dapat ikuwento."
    ),
    confirm: [
      t("Mark 5:19: Jesus told the freed man, \"Go home and tell how much the Lord has done for you.\"", "Marcos 5:19: sinabi ni Hesus sa pinalayang lalaki, \"Umuwi ka at ikuwento kung gaano kalaki ang ginawa sa iyo ng Panginoon.\""),
      t("John 4:39: many Samaritans believed because of the woman's testimony.", "Juan 4:39: maraming Samaritano ang sumampalataya dahil sa patotoo ng babae."),
      t("Acts 26:9-23: Paul told King Agrippa his own story of meeting Jesus.", "Gawa 26:9-23: ikinuwento ni Pablo kay Haring Agripa ang sarili niyang pagkakilala kay Hesus."),
      t("Revelation 12:11: they overcame by the blood of the Lamb and the word of their testimony.", "Pahayag 12:11: nagtagumpay sila sa dugo ng Kordero at sa salita ng kanilang patotoo."),
    ],
    heart: [
      t(
        "Move from shame about your past to gratitude for your Savior. What the enemy meant to silence you, God can use to speak through you.",
        "Lumipat mula sa kahihiyan sa nakaraan tungo sa pasasalamat sa Tagapagligtas mo. Ang ginamit ng kaaway para patahimikin ka ay magagamit ng Diyos para magsalita sa pamamagitan mo."
      ),
      t(
        "Let Jesus be the hero of your story. Humility tells the truth about yourself and gives all the glory to Him.",
        "Hayaang si Hesus ang bida sa kuwento mo. Ang kababaang-loob ay nagsasabi ng totoo tungkol sa sarili at ibinibigay ang lahat ng kaluwalhatian sa Kanya."
      ),
    ],
    questions: [
      t("What is your \"one thing I do know\" about what Jesus has done in your life?", "Ano ang \"isang bagay na alam ko\" tungkol sa ginawa ni Hesus sa buhay mo?"),
      t("What has kept you from telling your story more often: fear, shame, or feeling it is not dramatic enough?", "Ano ang pumipigil sa iyong ikuwento nang mas madalas ang patotoo mo: takot, hiya, o pakiramdam na hindi ito sapat na dramatiko?"),
      t("In your testimony, who is the hero, you or Jesus?", "Sa patotoo mo, sino ang bida, ikaw o si Hesus?"),
      t("Who in your life has never heard your story?", "Sino sa buhay mo ang hindi pa nakaririnig ng kuwento mo?"),
    ],
    actions: [
      t("Write your testimony in three parts (before, meeting, since) in about 250 words.", "Isulat ang patotoo mo sa tatlong bahagi (bago, pagkakilala, mula noon) sa mga 250 salita."),
      t("Practice telling it out loud in three minutes to a fellow believer and ask for feedback.", "Sanayin itong ikuwento nang malakas sa loob ng tatlong minuto sa kapwa mananampalataya at humingi ng feedback."),
      t("Pray for one opportunity this week and share your story with someone who does not yet know Jesus.", "Ipanalangin ang isang pagkakataon ngayong linggo at ibahagi ang kuwento mo sa isang hindi pa nakakakilala kay Hesus."),
    ],
    prayer: t(
      "Lord Jesus, I was blind and You opened my eyes. Thank You for every way You have rescued, kept and changed me. Take away my fear and my shame. Give me simple, honest words to tell what You have done, and let my story always point to You, not to me. Open doors this week for me to share it, and let those who hear come to know the joy of fellowship with You. Amen.",
      "Panginoong Hesus, bulag ako noon at binuksan Mo ang mga mata ko. Salamat sa bawat paraan ng pagliligtas, pag-iingat at pagbabago Mo sa akin. Alisin Mo ang takot at hiya ko. Bigyan Mo ako ng payak at tapat na salita para ikuwento ang ginawa Mo, at hayaang laging tumuro sa Iyo ang kuwento ko, hindi sa akin. Magbukas Ka ng mga pinto ngayong linggo para maibahagi ko ito, at hayaang makilala ng makaririnig ang kagalakan ng pakikisama sa Iyo. Amen."
    ),
  },

  "leading-someone-to-christ": {
    revelation: t(
      "God is already at work in the person in front of you; your part is to follow the Spirit's lead, explain Jesus clearly, and invite them to trust Him.",
      "Kumikilos na ang Diyos sa taong kaharap mo; ang bahagi mo ay sumunod sa pangunguna ng Espiritu, ipaliwanag si Hesus nang malinaw, at anyayahan siyang magtiwala sa Kanya."
    ),
    mainTruth: t(
      "An angel and then the Spirit sent Philip to a desert road, where an Ethiopian official was reading Isaiah 53. Philip ran to the chariot, asked, \"Do you understand what you are reading?\", and \"beginning with that very passage of Scripture told him the good news about Jesus.\" The man believed and was baptized (Acts 8:26-38). Paul summarizes the response God asks for: \"If you declare with your mouth, 'Jesus is Lord,' and believe in your heart that God raised Him from the dead, you will be saved\" (Romans 10:9-10). And Jesus told Nicodemus that this is not mere reform but new birth by the Spirit: \"You must be born again\" (John 3:1-8).",
      "Isang anghel at saka ang Espiritu ang nagpadala kay Felipe sa isang daan sa ilang, kung saan nagbabasa ng Isaias 53 ang isang opisyal na taga-Etiopia. Tumakbo si Felipe sa karwahe, nagtanong, \"Nauunawaan mo ba ang binabasa mo?\", at \"mula sa talatang iyon ay ipinahayag sa kanya ang mabuting balita tungkol kay Hesus.\" Sumampalataya ang lalaki at nabautismuhan (Gawa 8:26-38). Ibinuod ni Pablo ang tugong hinihingi ng Diyos: \"Kung ipapahayag mo ng iyong bibig na si Hesus ay Panginoon, at sasampalatayanan mo sa iyong puso na Siya'y muling binuhay ng Diyos, maliligtas ka\" (Roma 10:9-10). At sinabi ni Hesus kay Nicodemo na hindi lang ito pagbabagong-asal kundi bagong kapanganakan sa Espiritu: \"Kailangan kayong ipanganak na muli\" (Juan 3:1-8)."
    ),
    insight: [
      t(
        "We often imagine evangelism as forcing a conversation. But Philip did not create the moment; he joined it. God had already prepared the eunuch's heart and placed Isaiah 53 in his hands. Our job is to be sensitive and available, to \"go near that chariot\" when the Spirit nudges, and to start where the person is. Philip began with the man's own question and his own text. Good soul-winners listen before they speak.",
        "Madalas nating iniisip na ang ebanghelismo ay pagpipilit ng usapan. Pero hindi si Felipe ang gumawa ng sandali; nakisali lang siya. Inihanda na ng Diyos ang puso ng eunuko at inilagay ang Isaias 53 sa kamay niya. Ang trabaho natin ay maging sensitibo at handa, \"lumapit sa karwaheng iyon\" kapag kumikiliti ang Espiritu, at magsimula kung nasaan ang tao. Nagsimula si Felipe sa sariling tanong at sariling binabasa ng lalaki. Ang mahuhusay na tagapagdala ng kaluluwa ay nakikinig muna bago magsalita."
      ),
      t(
        "We also overlook that the new birth is God's work, not ours. Jesus told Nicodemus, \"The wind blows wherever it pleases... So it is with everyone born of the Spirit.\" This frees us from pressure. We cannot argue anyone into the kingdom, and we do not need to manipulate. We explain clearly, invite sincerely, and trust the Spirit to give life. That also means we keep praying when someone says, \"Not yet.\"",
        "Nakakaligtaan din natin na gawa ng Diyos ang bagong kapanganakan, hindi atin. Sabi ni Hesus kay Nicodemo, \"Umiihip ang hangin kung saan nito gusto... Ganyan din ang bawat ipinanganak sa Espiritu.\" Pinalalaya tayo nito sa pressure. Hindi natin kayang ipagtalo ang sinuman papasok sa kaharian, at hindi natin kailangang manipulahin. Ipinapaliwanag natin nang malinaw, nag-aanyaya nang tapat, at nagtitiwala sa Espiritu na magbigay-buhay. Ibig sabihin din nito, patuloy tayong mananalangin kapag may nagsabing, \"Hindi pa ngayon.\""
      ),
    ],
    life: [
      t(
        "Jun had shared about Jesus with his roommate Paolo many times in their Riyadh flat. One night Paolo asked, \"Bro, paano ba talaga maligtas?\" Jun's heart raced. He opened his phone Bible and explained simply: God loves us; our sin separates us; Jesus died for our sins and rose again; we receive Him by turning from sin and trusting Him as Lord. Then he asked, \"Do you want to trust Jesus now?\" Paolo said yes, and Jun helped him pray in his own words. It was not polished, but it was clear, and heaven rejoiced over one sinner who repented.",
        "Ilang beses nang nagbahagi si Jun tungkol kay Hesus sa roommate niyang si Paolo sa flat nila sa Riyadh. Isang gabi nagtanong si Paolo, \"Bro, paano ba talaga maligtas?\" Kumabog ang puso ni Jun. Binuksan niya ang Bible sa phone at ipinaliwanag nang simple: mahal tayo ng Diyos; inihihiwalay tayo ng kasalanan; namatay si Hesus para sa ating mga kasalanan at muling nabuhay; tinatanggap natin Siya sa pagtalikod sa kasalanan at pagtitiwala sa Kanya bilang Panginoon. Saka nagtanong siya, \"Gusto mo bang magtiwala kay Hesus ngayon?\" Oo ang sagot ni Paolo, at tinulungan siya ni Jun na manalangin sa sarili niyang salita. Hindi ito pulido, pero malinaw, at nagalak ang langit sa isang makasalanang nagsisi."
      ),
      t(
        "Many believers can explain the gospel but freeze at the invitation. It is like a salesman at a sari-sari store who describes the product beautifully but never asks, \"Bibili ka ba?\" Love asks. Gently, without pressure, ask: \"Is there anything stopping you from trusting Jesus today?\" Then listen. Either they are ready, or you learn what to pray about next.",
        "Maraming mananampalataya ang kayang ipaliwanag ang ebanghelyo pero natitigilan sa pag-aanyaya. Parang tindera sa sari-sari store na maganda ang paglalarawan sa produkto pero hindi nagtatanong, \"Bibili ka ba?\" Nagtatanong ang pag-ibig. Mahinahon at walang pamimilit, itanong: \"May pumipigil ba sa iyo na magtiwala kay Hesus ngayon?\" Saka makinig. Handa na siya, o malalaman mo kung ano ang susunod mong ipapanalangin."
      ),
    ],
    twist: t(
      "We think the hard part of leading someone to Christ is knowing what to say. But in Acts 8, the hardest part was the first step: leaving a successful revival in Samaria to walk to a lonely desert road for one person. The twist: God often measures a soul-winner not by crowds but by obedience to the one. Heaven threw a party for one lost sheep found (Luke 15:7). The person God puts in your path today may be your desert road.",
      "Akala natin ang mahirap sa pag-akay ng tao kay Cristo ay ang malaman kung ano ang sasabihin. Pero sa Gawa 8, ang pinakamahirap ay ang unang hakbang: iwan ang matagumpay na revival sa Samaria para maglakad sa malungkot na daan sa ilang para sa iisang tao. Ang twist: madalas sinusukat ng Diyos ang tagapagdala ng kaluluwa hindi sa dami ng tao kundi sa pagsunod para sa isa. Nagdiwang ang langit para sa isang nawawalang tupang natagpuan (Lucas 15:7). Ang taong inilagay ng Diyos sa landas mo ngayon ay maaaring ang daan mo sa ilang."
    ),
    confirm: [
      t("1 Corinthians 15:3-4: Christ died for our sins, was buried and was raised on the third day.", "1 Corinto 15:3-4: namatay si Cristo para sa ating mga kasalanan, inilibing at muling binuhay sa ikatlong araw."),
      t("Ephesians 2:8-9: saved by grace through faith, not by works.", "Efeso 2:8-9: ligtas dahil sa biyaya sa pamamagitan ng pananampalataya, hindi dahil sa gawa."),
      t("Acts 16:30-31: \"Believe in the Lord Jesus, and you will be saved.\"", "Gawa 16:30-31: \"Sumampalataya ka sa Panginoong Hesus, at maliligtas ka.\""),
      t("2 Corinthians 5:20: we are Christ's ambassadors, God making His appeal through us.", "2 Corinto 5:20: kami ay mga sugo ni Cristo, ang Diyos ang nakikiusap sa pamamagitan namin."),
    ],
    heart: [
      t(
        "Move from fear of rejection to compassion for the lost. The person in front of you matters more than your comfort.",
        "Lumipat mula sa takot na matanggihan tungo sa habag sa nawawala. Mas mahalaga ang taong kaharap mo kaysa sa ginhawa mo."
      ),
      t(
        "Let go of pressure and hold on to faithfulness. You plant and water; God gives the growth and the new birth.",
        "Bitawan ang pressure at kapitan ang katapatan. Ikaw ang nagtatanim at nagdidilig; ang Diyos ang nagpapalago at nagbibigay ng bagong kapanganakan."
      ),
    ],
    questions: [
      t("Could you explain the gospel clearly in two minutes right now?", "Kaya mo bang ipaliwanag ang ebanghelyo nang malinaw sa loob ng dalawang minuto ngayon?"),
      t("What stops you from inviting people to respond to Jesus?", "Ano ang pumipigil sa iyo na anyayahan ang mga tao na tumugon kay Hesus?"),
      t("Who is your \"Ethiopian on the desert road\", someone God seems to be preparing?", "Sino ang \"taga-Etiopia mo sa daan sa ilang\", isang taong mukhang inihahanda ng Diyos?"),
      t("Are you sensitive and available when the Spirit nudges you, or too busy to notice?", "Sensitibo at handa ka ba kapag kumikiliti ang Espiritu, o masyadong abala para mapansin?"),
    ],
    actions: [
      t("Practice explaining the gospel using Romans 10:9-10 and 1 Corinthians 15:3-4 with a fellow believer.", "Sanaying ipaliwanag ang ebanghelyo gamit ang Roma 10:9-10 at 1 Corinto 15:3-4 kasama ang kapwa mananampalataya."),
      t("Write the names of three people who do not know Jesus and pray for an open door daily.", "Isulat ang pangalan ng tatlong taong hindi pa kilala si Hesus at ipanalangin araw-araw ang bukas na pinto."),
      t("When the moment comes, gently ask, \"Would you like to trust Jesus today?\" and be ready to pray with them.", "Pagdating ng sandali, mahinahong itanong, \"Gusto mo bang magtiwala kay Hesus ngayon?\" at maging handang manalangin kasama niya."),
    ],
    prayer: t(
      "Holy Spirit, You sent Philip to one man on a desert road. Send me too, and make me willing to go. Open my eyes to the people You are already preparing. Give me courage to start the conversation, clarity to explain the cross and the empty tomb, and love to invite without pressure. Do what only You can do: give new birth. Let heaven rejoice over someone this year because I obeyed. Amen.",
      "Banal na Espiritu, ipinadala Mo si Felipe sa iisang tao sa daan sa ilang. Ipadala Mo rin ako, at gawin Mo akong handang humayo. Buksan Mo ang mga mata ko sa mga taong inihahanda Mo na. Bigyan Mo ako ng tapang na simulan ang usapan, linaw sa pagpapaliwanag ng krus at ng walang-lamang libingan, at pag-ibig na mag-anyaya nang walang pamimilit. Gawin Mo ang Ikaw lang ang makagagawa: magbigay ng bagong kapanganakan. Hayaang magdiwang ang langit para sa isang tao ngayong taon dahil sumunod ako. Amen."
    ),
  },

  "the-first-thirty-days": {
    revelation: t(
      "A decision for Christ is a birth, not a finish line, and the love you show in the first thirty days helps a new believer put down roots that will hold for a lifetime.",
      "Ang pagpapasya para kay Cristo ay kapanganakan, hindi finish line, at ang pag-ibig na ipinapakita mo sa unang tatlumpung araw ay tumutulong sa bagong mananampalataya na mag-ugat nang matibay habambuhay."
    ),
    mainTruth: t(
      "After preaching in Derbe and winning many disciples, Paul and Barnabas went back through Lystra, Iconium and Antioch, \"strengthening the disciples and encouraging them to remain true to the faith,\" telling them honestly, \"We must go through many hardships to enter the kingdom of God,\" and appointing elders with prayer and fasting (Acts 14:21-23). Paul later wrote, \"Just as you received Christ Jesus as Lord, continue to live your lives in Him, rooted and built up in Him, strengthened in the faith as you were taught\" (Colossians 2:6-7). And Paul's own instinct was, \"Let us go back and visit the believers in all the towns... and see how they are doing\" (Acts 15:36). Follow-up is apostolic, not optional.",
      "Matapos mangaral sa Derbe at makahikayat ng maraming alagad, bumalik sina Pablo at Bernabe sa Listra, Iconio at Antioquia, \"pinatatatag ang loob ng mga alagad at hinihimok silang manatili sa pananampalataya,\" tapat na sinasabi, \"Kailangan nating dumaan sa maraming kapighatian bago pumasok sa kaharian ng Diyos,\" at naghirang ng matatanda sa panalangin at pag-aayuno (Gawa 14:21-23). Sumulat si Pablo pagkatapos, \"Kung paanong tinanggap ninyo si Cristo Hesus bilang Panginoon, mamuhay kayo sa Kanya, nakaugat at itinatayo sa Kanya, pinatatatag sa pananampalataya gaya ng itinuro sa inyo\" (Colosas 2:6-7). At ang likas na hangarin ni Pablo ay, \"Balikan natin ang mga kapatid sa lahat ng bayan... at tingnan kung kumusta sila\" (Gawa 15:36). Ang follow-up ay gawaing apostoliko, hindi opsyonal."
    ),
    insight: [
      t(
        "Notice that Paul went back to cities where he had been stoned and left for dead (Acts 14:19). He risked his life to follow up. Many of us will not risk an awkward text message. Paul understood that a church without follow-up is like a farmer who plants and never returns to water. The harvest is not lost in the planting; it is lost in the neglect afterward.",
        "Pansinin na bumalik si Pablo sa mga lungsod kung saan siya binato at iniwang akala'y patay na (Gawa 14:19). Isinugal niya ang buhay para sa follow-up. Marami sa atin ang ayaw magsugal kahit sa isang awkward na text message. Naunawaan ni Pablo na ang simbahang walang follow-up ay parang magsasakang nagtanim at hindi na bumalik para magdilig. Hindi nawawala ang ani sa pagtatanim; nawawala ito sa kapabayaan pagkatapos."
      ),
      t(
        "Notice also what Paul said to new believers: \"We must go through many hardships.\" He did not promise them an easy life. Many new believers fall away not because the gospel failed, but because no one warned them that trials would come. Honest follow-up prepares people: the first temptation, the first mocking relative, the first unanswered prayer. When it comes, they will remember, \"My discipler told me this would happen, and that God would hold me.\"",
        "Pansinin din ang sinabi ni Pablo sa bagong mananampalataya: \"Kailangan nating dumaan sa maraming kapighatian.\" Hindi niya ipinangako ang madaling buhay. Maraming bagong mananampalataya ang tumatalikod hindi dahil nabigo ang ebanghelyo, kundi dahil walang nagbabala sa kanila na darating ang pagsubok. Inihahanda ng tapat na follow-up ang mga tao: ang unang tukso, ang unang kamag-anak na manunuya, ang unang panalanging parang hindi sinagot. Pagdating nito, maaalala nila, \"Sinabi ito ng discipler ko, at sinabi rin niyang hahawakan ako ng Diyos.\""
      ),
    ],
    life: [
      t(
        "A simple thirty-day plan can change everything. Week one: meet or call within 48 hours, explain assurance of salvation (1 John 5:11-13), give them a Bible app or printed Gospel of John, and pray together. Week two: teach a simple daily habit of reading and prayer. Week three: bring them to church and a small group, and introduce them to friends. Week four: talk about baptism, sharing their story with one person, and dealing with temptation. Not complicated, just consistent.",
        "Puwedeng magbago ang lahat sa isang simpleng plano ng tatlumpung araw. Unang linggo: magkita o tumawag sa loob ng 48 oras, ipaliwanag ang katiyakan ng kaligtasan (1 Juan 5:11-13), bigyan siya ng Bible app o nakaimprentang Ebanghelyo ni Juan, at manalangin nang magkasama. Ikalawang linggo: ituro ang simpleng araw-araw na ugali ng pagbabasa at panalangin. Ikatlong linggo: isama siya sa simbahan at sa small group, at ipakilala sa mga kaibigan. Ikaapat na linggo: pag-usapan ang bautismo, ang pagbabahagi ng kuwento niya sa isang tao, at ang pagharap sa tukso. Hindi komplikado, tuloy-tuloy lang."
      ),
      t(
        "Think of a newly planted rice seedling. The first weeks after transplanting decide whether it takes root or floats away. Farmers in the province check their paddies daily during that stage. A new believer is like that seedling. A daily short message, \"Nakabasa ka na ba today? What did God show you?\", may feel small to you. To them, it is water at the right time.",
        "Isipin ang bagong lipat na punla ng palay. Ang unang mga linggo pagkatapos ilipat ang magpapasya kung mag-uugat ito o lulutang palayo. Araw-araw tinitingnan ng mga magsasaka sa probinsya ang palayan nila sa yugtong iyon. Ganyan ang bagong mananampalataya. Ang maikling araw-araw na mensahe, \"Nakabasa ka na ba today? Ano ang ipinakita sa iyo ng Diyos?\", ay maaaring maliit para sa iyo. Para sa kanila, tubig ito sa tamang oras."
      ),
    ],
    twist: t(
      "We often treat follow-up as the boring part after the exciting part of evangelism. But Jesus did not say, \"Go and make decisions\"; He said, \"Go and make disciples... teaching them to obey\" (Matthew 28:19-20). The twist: in God's eyes, follow-up is not after the mission; it is the mission. A decision that is never nurtured may wither, but a disciple who is rooted will bear fruit for generations.",
      "Madalas nating tinatrato ang follow-up bilang nakakabagot na bahagi pagkatapos ng kapana-panabik na ebanghelismo. Pero hindi sinabi ni Hesus, \"Humayo kayo at gumawa ng desisyon\"; sinabi Niya, \"Humayo kayo at gumawa ng alagad... turuan silang sumunod\" (Mateo 28:19-20). Ang twist: sa paningin ng Diyos, ang follow-up ay hindi pagkatapos ng misyon; ito mismo ang misyon. Ang desisyong hindi inalagaan ay maaaring malanta, pero ang alagad na nakaugat ay mamumunga sa mga henerasyon."
    ),
    confirm: [
      t("Mark 4:16-17: some receive the word with joy but fall away when trouble comes because they have no root.", "Marcos 4:16-17: may tumatanggap ng salita nang may galak pero tumatalikod pagdating ng kaguluhan dahil walang ugat."),
      t("Acts 2:41-42: three thousand were baptized and devoted themselves to the apostles' teaching and fellowship.", "Gawa 2:41-42: tatlong libo ang nabautismuhan at inilaan ang sarili sa turo ng mga apostol at pagsasama."),
      t("Philippians 1:6: He who began a good work will carry it on to completion.", "Filipos 1:6: ang nagsimula ng mabuting gawa ay tatapusin ito."),
      t("1 Thessalonians 3:1-5: Paul sent Timothy to strengthen the new believers so trials would not unsettle them.", "1 Tesalonica 3:1-5: ipinadala ni Pablo si Timoteo para patatagin ang bagong mananampalataya upang hindi sila matinag ng pagsubok."),
    ],
    heart: [
      t(
        "Move from celebrating decisions to investing in disciples. Let your joy over a new believer turn into faithful, patient care.",
        "Lumipat mula sa pagdiriwang ng desisyon tungo sa pamumuhunan sa alagad. Hayaang maging tapat at matiyagang pag-aalaga ang kagalakan mo sa bagong mananampalataya."
      ),
      t(
        "Become someone who goes back. Like Paul, care enough to ask, \"How are they doing?\" and then go and see.",
        "Maging taong bumabalik. Gaya ni Pablo, magmalasakit na magtanong, \"Kumusta na kaya sila?\" at saka puntahan."
      ),
    ],
    questions: [
      t("Who followed you up in your first month, and what difference did it make?", "Sino ang nag-follow up sa iyo sa unang buwan mo, at ano ang naging epekto nito?"),
      t("Is there someone who made a decision for Christ near you whom no one has followed up?", "May tao bang nagpasya para kay Cristo malapit sa iyo na walang nag-follow up?"),
      t("Do you prepare new believers honestly for hardship, or only promise blessing?", "Inihahanda mo ba nang tapat ang bagong mananampalataya sa kahirapan, o pagpapala lang ang ipinapangako mo?"),
      t("What would it cost you to commit to one person for the next thirty days?", "Ano ang magiging halaga sa iyo kung mag-commit ka sa isang tao sa susunod na tatlumpung araw?"),
    ],
    actions: [
      t("Write a simple four-week follow-up plan you could use with any new believer.", "Sumulat ng simpleng apat na linggong plano ng follow-up na magagamit mo sa kahit sinong bagong mananampalataya."),
      t("Contact a new or returning believer within 48 hours and schedule your first meeting.", "Kontakin ang isang bago o nagbabalik na mananampalataya sa loob ng 48 oras at itakda ang una ninyong pagkikita."),
      t("Send a short encouraging message with one Bible verse to them every day this week.", "Magpadala ng maikling nakapagpapalakas na mensahe na may isang talata ng Bibliya araw-araw ngayong linggo."),
    ],
    prayer: t(
      "Lord, You never abandon what You begin. Give me a heart like Paul's that goes back to strengthen the young in faith. Show me the new believers who need someone, and make me faithful in the small daily things: a call, a verse, a prayer. Help me prepare them honestly for hardship and point them to Your faithfulness. Root them deeply in Christ, so they may stand firm and bear fruit. Amen.",
      "Panginoon, hindi Mo iniiwan ang sinimulan Mo. Bigyan Mo ako ng pusong gaya ni Pablo na bumabalik para patatagin ang mga bata pa sa pananampalataya. Ipakita Mo sa akin ang bagong mananampalatayang nangangailangan ng kasama, at gawin Mo akong tapat sa maliliit na araw-araw na bagay: isang tawag, isang talata, isang panalangin. Tulungan Mo akong ihanda sila nang tapat sa kahirapan at ituro sila sa Iyong katapatan. Iugat Mo sila nang malalim kay Cristo, para tumayo silang matatag at mamunga. Amen."
    ),
  },

  "one-on-one-discipleship": {
    revelation: t(
      "Some of the deepest transformation happens not in crowds but in one faithful life walking closely beside another, where faith is seen up close and love is proven over time.",
      "Ang ilan sa pinakamalalim na pagbabago ay nangyayari hindi sa maraming tao kundi sa isang tapat na buhay na malapit na sumasabay sa isa pa, kung saan nakikita nang malapitan ang pananampalataya at napapatunayan ang pag-ibig sa paglipas ng panahon."
    ),
    mainTruth: t(
      "Paul reminds Timothy, \"You, however, know all about my teaching, my way of life, my purpose, faith, patience, love, endurance, persecutions, sufferings,\" and urges him to continue in what he has learned, \"because you know those from whom you learned it,\" and because all Scripture is God-breathed and equips the servant of God for every good work (2 Timothy 3:10-17). Timothy learned from Paul's life, not only his letters. Long before, Ruth bound her life to Naomi: \"Where you go I will go, and where you stay I will stay. Your people will be my people and your God my God\" (Ruth 1:16-18). One-on-one discipleship is a covenant of shared life, anchored in Scripture.",
      "Ipinaalala ni Pablo kay Timoteo, \"Ngunit ikaw ay sumunod sa aking turo, pamumuhay, layunin, pananampalataya, pagtitiyaga, pag-ibig, pagtitiis, mga pag-uusig at mga paghihirap,\" at hinimok siyang magpatuloy sa natutunan niya, \"dahil kilala mo ang mga nagturo sa iyo,\" at dahil ang lahat ng Kasulatan ay hiningahan ng Diyos at nagsasangkap sa lingkod ng Diyos para sa bawat mabuting gawa (2 Timoteo 3:10-17). Natuto si Timoteo sa buhay ni Pablo, hindi lang sa mga sulat niya. Matagal bago noon, itinali ni Ruth ang buhay niya kay Naomi: \"Kung saan ka pumunta, doon ako pupunta, at kung saan ka tumira, doon ako titira. Ang bayan mo ay magiging bayan ko at ang Diyos mo ay magiging Diyos ko\" (Ruth 1:16-18). Ang one-on-one discipleship ay tipan ng pinagsasaluhang buhay, nakaangkla sa Kasulatan."
    ),
    insight: [
      t(
        "Notice the list Paul gives Timothy: teaching first, but then way of life, purpose, patience, love, and even sufferings. Timothy had seen Paul on good days and bad days. One-on-one discipleship lets someone see how you handle money, criticism, disappointment and temptation. That is exactly why many avoid it: it exposes us. But that exposure is the gift. Disciples need to see not a perfect Christian, but a real one who keeps returning to Jesus.",
        "Pansinin ang listahang ibinigay ni Pablo kay Timoteo: turo muna, pero pagkatapos ay pamumuhay, layunin, pagtitiyaga, pag-ibig, at pati mga paghihirap. Nakita ni Timoteo si Pablo sa magaganda at masasamang araw. Sa one-on-one discipleship, nakikita ng tao kung paano mo hinaharap ang pera, puna, pagkabigo at tukso. Iyan mismo ang dahilan kung bakit marami ang umiiwas: inilalantad tayo nito. Pero regalo ang paglalantad na iyon. Hindi kailangan ng mga alagad na makakita ng perpektong Kristiyano, kundi ng totoo na patuloy na bumabalik kay Hesus."
      ),
      t(
        "Ruth and Naomi show something we rarely notice: Naomi was bitter and broken (Ruth 1:20-21), yet God used her to lead Ruth to Him. Naomi did not feel like a good mentor. She had nothing to offer but her honest faith in Israel's God and her company. Your discipleship does not depend on having it all together. It depends on staying faithful and letting God work through your weakness, just as He did through Naomi.",
        "Ipinapakita nina Ruth at Naomi ang bihira nating mapansin: mapait at wasak si Naomi (Ruth 1:20-21), pero ginamit siya ng Diyos para akayin si Ruth sa Kanya. Hindi pakiramdam ni Naomi na mabuting mentor siya. Wala siyang maialok kundi ang tapat niyang pananampalataya sa Diyos ng Israel at ang pakikisama niya. Hindi nakasalalay ang discipleship mo sa pagiging buo ng lahat sa iyo. Nakasalalay ito sa pananatiling tapat at sa paghayaang kumilos ang Diyos sa kahinaan mo, gaya ng ginawa Niya kay Naomi."
      ),
    ],
    life: [
      t(
        "Every Saturday morning, Ate Cora, a nurse in Kuwait, meets with Bea, a younger nurse, at the same small café. They read one passage, Bea asks questions, they talk about work and family, and they pray. Some Saturdays are deep; some are just Bea crying about a difficult ward manager. After a year, Bea said, \"I learned more from watching you deal with that unfair schedule than from any sermon.\" That is 2 Timothy 3:10 in a Kuwaiti café.",
        "Tuwing Sabado ng umaga, nakikipagkita si Ate Cora, isang nurse sa Kuwait, kay Bea, isang mas batang nurse, sa iisang maliit na café. Nagbabasa sila ng isang talata, nagtatanong si Bea, nag-uusap sila tungkol sa trabaho at pamilya, at nananalangin. May mga Sabadong malalim ang usapan; may mga Sabadong umiiyak lang si Bea tungkol sa mahirap na ward manager. Pagkatapos ng isang taon, sabi ni Bea, \"Mas marami akong natutunan sa panonood kung paano mo hinarap ang hindi patas na iskedyul kaysa sa kahit anong sermon.\" Iyan ang 2 Timoteo 3:10 sa isang café sa Kuwait."
      ),
      t(
        "A simple rhythm helps one-on-one discipleship: share (\"How is your soul this week?\"), Scripture (read one passage and ask what God is saying), struggle (\"Where are you being tempted or tested?\"), step (\"What is one thing you will obey this week?\"), and prayer. Meet regularly, keep confidences, and be honest about your own walk too. Discipleship is not a teacher pouring into an empty jar; it is two people walking toward Jesus together, one a little ahead.",
        "Nakakatulong ang simpleng ritmo sa one-on-one discipleship: kumustahan (\"Kumusta ang kaluluwa mo ngayong linggo?\"), Kasulatan (magbasa ng isang talata at itanong kung ano ang sinasabi ng Diyos), pakikibaka (\"Saan ka tinutukso o sinusubok?\"), hakbang (\"Ano ang isang bagay na susundin mo ngayong linggo?\"), at panalangin. Regular na magkita, ingatan ang mga lihim, at maging tapat din tungkol sa sarili mong lakad. Ang discipleship ay hindi guro na nagbubuhos sa bakanteng banga; ito ay dalawang taong sabay na naglalakad patungo kay Hesus, ang isa ay medyo nauuna lang."
      ),
    ],
    twist: t(
      "We assume the mature believer is the one who gives and the younger one is the one who receives. But in Ruth's story, the young foreign widow's loyalty became the very thing God used to restore bitter Naomi, and through Ruth came King David and eventually Jesus (Ruth 4:13-17; Matthew 1:5). The twist: in one-on-one discipleship, God often blesses the discipler as much as the disciple. The one you are helping may be God's gift to heal you too.",
      "Inaakala nating ang mas matandang mananampalataya ang nagbibigay at ang mas bata ang tumatanggap. Pero sa kuwento ni Ruth, ang katapatan ng batang balong dayuhan ang mismong ginamit ng Diyos para ibalik ang mapait na si Naomi, at mula kay Ruth nagmula si Haring David at kalaunan si Hesus (Ruth 4:13-17; Mateo 1:5). Ang twist: sa one-on-one discipleship, madalas pinagpapala ng Diyos ang discipler gaya ng pagpapala Niya sa disipulo. Ang taong tinutulungan mo ay maaaring regalo ng Diyos para pagalingin ka rin."
    ),
    confirm: [
      t("1 Samuel 18:1-4; 23:16: Jonathan helped David find strength in God.", "1 Samuel 18:1-4; 23:16: tinulungan ni Jonathan si David na makasumpong ng lakas sa Diyos."),
      t("2 Kings 2:1-15: Elisha refused to leave Elijah and received a double portion.", "2 Hari 2:1-15: tumangging iwan ni Eliseo si Elias at tumanggap ng dobleng bahagi."),
      t("Acts 18:24-26: Priscilla and Aquila took Apollos aside and explained the way of God more accurately.", "Gawa 18:24-26: tinabihan nina Priscila at Aquila si Apolos at ipinaliwanag nang mas wasto ang daan ng Diyos."),
      t("Proverbs 27:17: as iron sharpens iron, so one person sharpens another.", "Kawikaan 27:17: kung paanong ang bakal ay nagpapatalas ng bakal, gayon ang tao sa kapwa niya."),
    ],
    heart: [
      t(
        "Move from hiding your life to opening it. Let someone see your real walk with God, including your struggles and repentance.",
        "Lumipat mula sa pagtatago ng buhay mo tungo sa pagbubukas nito. Hayaang makita ng iba ang totoo mong lakad kasama ang Diyos, pati ang mga pakikibaka at pagsisisi mo."
      ),
      t(
        "Commit like Ruth: loyal, patient and present through the seasons, not only when it is convenient.",
        "Mag-commit gaya ni Ruth: tapat, matiyaga at presente sa lahat ng panahon, hindi lang kapag maginhawa."
      ),
    ],
    questions: [
      t("Who has been your \"Paul\" or \"Naomi\", and what did you learn from their life?", "Sino ang naging \"Pablo\" o \"Naomi\" mo, at ano ang natutunan mo sa buhay nila?"),
      t("What part of your life would you be afraid for a disciple to see up close? Why?", "Anong bahagi ng buhay mo ang ikakatakot mong makita nang malapitan ng isang disipulo? Bakit?"),
      t("Do you feel too broken to disciple someone? What does Naomi's story say to you?", "Pakiramdam mo ba masyado kang wasak para magdisciple? Ano ang sinasabi sa iyo ng kuwento ni Naomi?"),
      t("Who is one person you could commit to meet with regularly for the next six months?", "Sino ang isang taong puwede mong i-commit na regular na makipagkita sa susunod na anim na buwan?"),
    ],
    actions: [
      t("Pray and ask one person to meet with you weekly for discipleship, agreeing on a time and place.", "Manalangin at anyayahan ang isang tao na makipagkita sa iyo linggo-linggo para sa discipleship, at pagkasunduan ang oras at lugar."),
      t("Use the rhythm of share, Scripture, struggle, step and prayer in your first meeting.", "Gamitin ang ritmong kumustahan, Kasulatan, pakikibaka, hakbang at panalangin sa una ninyong pagkikita."),
      t("Share one honest struggle of your own with your disciple and how you are bringing it to Jesus.", "Ibahagi sa disipulo mo ang isang tapat mong pakikibaka at kung paano mo ito dinadala kay Hesus."),
    ],
    prayer: t(
      "Father, thank You for the Pauls and Naomis You placed in my life. Make me that kind of person for someone else. Give me courage to open my life, honesty to show my weakness, and faithfulness to stay through every season. Let Your Word be the foundation of every meeting. Use my brokenness the way You used Naomi's, and let the one I walk with become fully equipped for every good work. Amen.",
      "Ama, salamat sa mga Pablo at Naomi na inilagay Mo sa buhay ko. Gawin Mo akong ganoong tao para sa iba. Bigyan Mo ako ng tapang na buksan ang buhay ko, katapatan na ipakita ang kahinaan ko, at tiyagang manatili sa bawat panahon. Gawin Mong pundasyon ng bawat pagkikita ang Iyong Salita. Gamitin Mo ang pagkawasak ko gaya ng paggamit Mo sa kay Naomi, at hayaang ang kasama kong naglalakad ay maging ganap na nasangkapan para sa bawat mabuting gawa. Amen."
    ),
  },
  "a-healthy-small-group": {
    revelation: t(
      "A healthy small group is not built on a gifted leader at the front but on a welcoming family where everyone bears one another's burdens.",
      "Ang malusog na small group ay hindi itinatayo sa mahusay na lider sa harap kundi sa magiliw na pamilya kung saan ang bawat isa ay nagpapasan ng pasanin ng isa't isa."
    ),
    mainTruth: t(
      "\"Welcome one another as Christ has welcomed you, for the glory of God\" (Romans 15:7). Paul calls the strong to bear with the failings of the weak, not to please themselves but to build up their neighbor (Romans 15:1-2), and to live in harmony together so that with one voice they may glorify God (Romans 15:5-6). Galatians adds the heart of it: \"Bear one another's burdens, and so fulfill the law of Christ,\" while each one carries his own load before God (Galatians 6:2, 5).",
      "\"Tanggapin ninyo ang isa't isa gaya ng pagtanggap sa inyo ni Cristo, para sa kaluwalhatian ng Diyos\" (Roma 15:7). Tinatawag ni Pablo ang malalakas na magdala ng kahinaan ng mahihina, hindi para bigyang-lugod ang sarili kundi para patatagin ang kapwa (Roma 15:1-2), at mamuhay nang magkakasundo upang sa iisang tinig ay luwalhatiin ang Diyos (Roma 15:5-6). Idinadagdag ng Galacia ang puso nito: \"Pasanin ninyo ang pasanin ng isa't isa, at sa gayon ay matutupad ninyo ang kautusan ni Cristo,\" habang dala ng bawat isa ang sarili niyang pasanin sa harap ng Diyos (Galacia 6:2, 5)."
    ),
    insight: [
      t(
        "Many leaders think a good group means a good lesson. But people rarely remember the outline; they remember how they felt: Was I seen? Was I safe to be honest? The group's health is measured by welcome, not by performance. Romans 15:7 says to welcome one another as Christ welcomed you: with your faults, your questions, and your story. If Christ's welcome is the standard, no one has to earn a seat.",
        "Maraming lider ang nag-aakalang ang mahusay na group ay mahusay na leksiyon. Pero bihirang matandaan ng tao ang balangkas; naaalala nila ang pakiramdam: Nakita ba ako? Ligtas ba akong maging tapat? Sinusukat ang kalusugan ng group sa pagtanggap, hindi sa pagganap. Sabi ng Roma 15:7, tanggapin ang isa't isa gaya ng pagtanggap sa iyo ni Cristo: kasama ang mga kapintasan, tanong at kuwento mo. Kung ang pagtanggap ni Cristo ang sukatan, walang kailangang kumita ng upuan."
      ),
      t(
        "Notice the balance in Galatians 6: bear one another's burdens (verse 2), yet each carries his own load (verse 5). A healthy group does not rescue people from every responsibility, nor does it leave them alone in a crisis. The \"burdens\" are crushing weights like grief and sin; the \"load\" is daily responsibility. A good leader knows which one he is looking at, and helps people to stand, not to lean forever.",
        "Pansinin ang balanse sa Galacia 6: pasanin ang pasanin ng isa't isa (t. 2), ngunit dala ng bawat isa ang sarili niyang karga (t. 5). Ang malusog na group ay hindi sumasalo sa tao sa bawat responsibilidad, at hindi rin siya iniiwan sa krisis. Ang \"pasanin\" ay mabibigat na bagay gaya ng pagdadalamhati at kasalanan; ang \"karga\" ay pang-araw-araw na responsibilidad. Alam ng mabuting lider kung alin ang tinitingnan niya, at tinutulungan ang tao na tumayo, hindi sumandal habambuhay."
      ),
    ],
    life: [
      t(
        "Picture a Thursday night group in a rented flat in Dubai. Ten people, tired from shifts, share rice and pancit. Bong, the leader, does not preach; he asks, \"Ano'ng pinagdaanan ninyo ngayong linggo?\" One sister cries about her mother's illness back home; two others pray with her; someone offers to send groceries to the family. That evening no one gave a clever message, yet everyone left lighter.",
        "Isipin ang group tuwing Huwebes ng gabi sa inuupahang flat sa Dubai. Sampung taong pagod sa shift ang nagsasalo ng kanin at pansit. Si Bong, ang lider, ay hindi nagsesermon; nagtatanong siya, \"Ano'ng pinagdaanan ninyo ngayong linggo?\" Umiyak ang isang sister tungkol sa karamdaman ng nanay niya sa Pilipinas; dalawa ang nagdasal kasama niya; may nag-alok magpadala ng grocery sa pamilya. Walang nagbigay ng matalinong mensahe nang gabing iyon, pero gumaan ang pakiramdam ng lahat."
      ),
      t(
        "Healthy leadership also means guarding the group: not letting one person dominate every discussion, gently redirecting gossip, protecting confidences, and praying for the quiet ones. Keep it simple: share a meal, open the Word, listen, pray, and send people out to serve. Sustain it with a rhythm and with the help of a co-leader.",
        "Kasama rin sa malusog na pamumuno ang pagbabantay sa group: hindi hinahayaang manguna ang isang tao sa bawat usapan, marahang inililihis ang tsismis, iniingatan ang mga lihim, at ipinapanalangin ang mga tahimik. Gawing simple: magsalo ng pagkain, buksan ang Salita, making, manalangin, at isugo ang mga tao para maglingkod. Panatilihin ito sa regular na ritmo at sa tulong ng kasamang lider."
      ),
    ],
    twist: t(
      "We assume the leader's job is to have all the answers. The Kingdom twist is that the best leaders create space for the Holy Spirit to speak through others. Paul says each member has something to contribute (1 Corinthians 14:26). A group where the leader talks eighty percent of the time is a class; a group where everyone shares is a body. The leader who steps back often lets Christ step forward.",
      "Akala natin trabaho ng lider ang magkaroon ng lahat ng sagot. Ang twist ng Kaharian: ang pinakamahusay na lider ay gumagawa ng espasyo para magsalita ang Banal na Espiritu sa pamamagitan ng iba. Sabi ni Pablo, bawat miyembro ay may maiaambag (1 Corinto 14:26). Ang group na walumpung porsiyento ng oras ay ang lider ang nagsasalita ay klase; ang group na lahat ay nagbabahagi ay katawan. Ang lider na madalas umatras ay hinahayaan si Cristo na humakbang pasulong."
    ),
    confirm: [
      t("Acts 2:42-47: the early believers shared meals, prayers, teaching and possessions in homes.", "Gawa 2:42-47: nagsasalo ng pagkain, panalangin, turo at ari-arian ang mga unang mananampalataya sa mga tahanan."),
      t("Hebrews 10:24-25: consider how to stir one another up to love and good works, not neglecting to meet.", "Hebreo 10:24-25: pag-isipan kung paano pasiglahin ang isa't isa sa pag-ibig at mabubuting gawa, at huwag pabayaan ang pagtitipon."),
      t("Exodus 18:17-23: Jethro told Moses to share the load with trusted leaders.", "Exodo 18:17-23: sinabihan ni Jetro si Moises na ibahagi ang karga sa mga mapagkakatiwalaang lider."),
      t("1 Thessalonians 2:7-8: Paul cared for them like a nursing mother, sharing his very self.", "1 Tesalonica 2:7-8: inalagaan sila ni Pablo na parang inang nag-aaruga, ibinabahagi ang kanyang sarili."),
    ],
    heart: [
      t(
        "Lead with welcome before wisdom. Be the first to listen, the first to share a weakness, and the last to correct.",
        "Mamuno nang may pagtanggap bago karunungan. Maging una sa pakikinig, una sa pag-amin ng kahinaan, at huli sa pagtatama."
      ),
      t(
        "Release control. Trust the Spirit, raise up others, and be willing to be one voice among many.",
        "Bitiwan ang kontrol. Magtiwala sa Espiritu, magpalaki ng iba, at maging handang isang tinig lang sa marami."
      ),
    ],
    questions: [
      t("Would a newcomer or a struggling person feel welcomed in my group?", "Mararamdaman ba ng bagong dating o nahihirapang tao na welcome siya sa group ko?"),
      t("How much of the time am I talking, compared to the others?", "Gaano katagal akong nagsasalita kumpara sa iba?"),
      t("Is there anyone quiet or missing whom I should check on this week?", "May tahimik ba o hindi dumarating na dapat kong kumustahin ngayong linggo?"),
      t("Who could I train as a co-leader or future leader?", "Sino ang puwede kong sanayin bilang kasamang lider o hinaharap na lider?"),
    ],
    actions: [
      t("Plan your next meeting with four parts: share a meal or check-in, read the Word, listen, and pray for one another.", "Planuhin ang susunod na pagtitipon sa apat na bahagi: pagsasalo o kumustahan, pagbasa ng Salita, pakikinig, at pagdarasal para sa isa't isa."),
      t("Message one member who has been quiet and tell them you are glad they are in the group.", "Mag-message sa isang miyembrong tahimik at sabihing masaya ka na kasama siya sa group."),
      t("Invite one person to co-lead part of the next session, such as the opening prayer or one question.", "Anyayahan ang isang tao na mag-co-lead ng bahagi ng susunod na sesyon, tulad ng panimulang dasal o isang tanong."),
    ],
    prayer: t(
      "Lord Jesus, You welcomed me when I had nothing to offer. Help me to welcome others the same way. Make my group a family where people can be honest, find comfort and grow in Your Word. Keep me from dominating, and teach me to listen. Give me wisdom to guard the group from gossip and division, and a heart that bears the burdens of others. Raise up leaders among us. Let our gatherings bring glory to You. In Your name, Amen.",
      "Panginoong Hesus, tinanggap Mo ako noong wala akong maialay. Tulungan Mo akong tanggapin ang iba sa ganoon ding paraan. Gawin Mong pamilya ang group ko kung saan puwedeng maging tapat ang mga tao, makahanap ng aliw at lumago sa Iyong Salita. Ilayo Mo akong manguna nang sobra, at turuan Mo akong making. Bigyan Mo ako ng karunungang bantayan ang group laban sa tsismis at pagkakawatak-watak, at pusong nagpapasan ng pasanin ng iba. Magbangon Ka ng mga lider sa amin. Hayaang magdala ng kaluwalhatian sa Iyo ang aming mga pagtitipon. Sa pangalan Mo, Amen."
    ),
  },
  "correcting-with-gentleness": {
    revelation: t(
      "Truth spoken without love wounds, and love without truth cheats; real correction is truth carried gently by someone who also knows he needs grace.",
      "Ang katotohanang sinasabi nang walang pag-ibig ay nananakit, at ang pag-ibig na walang katotohanan ay nanlilinlang; ang tunay na pagtutuwid ay katotohanang buhat nang marahan ng taong alam ding kailangan niya ng biyaya."
    ),
    mainTruth: t(
      "\"The Lord's servant must not be quarrelsome but kind to everyone, able to teach, patiently enduring evil, correcting his opponents with gentleness. God may perhaps grant them repentance leading to a knowledge of the truth\" (2 Timothy 2:24-25). \"Faithful are the wounds of a friend\" (Proverbs 27:6). And Paul: \"If anyone is caught in any transgression, you who are spiritual should restore him in a spirit of gentleness. Keep watch on yourself, lest you too be tempted\" (Galatians 6:1).",
      "\"Ang lingkod ng Panginoon ay hindi dapat palaaway kundi mabait sa lahat, may kakayahang magturo, matiisin sa masama, at marahang nagtutuwid sa mga kumakalaban. Baka sakaling ipagkaloob sa kanila ng Diyos ang pagsisisi na umaakay sa pagkakilala sa katotohanan\" (2 Timoteo 2:24-25). \"Tapat ang mga sugat ng kaibigan\" (Kawikaan 27:6). At si Pablo: \"Kung may mahuli sa anumang pagkakasala, kayong mga espirituwal ay ibalik siya nang may espiritu ng kahinahunan. Bantayan ninyo ang inyong sarili, baka kayo man ay matukso\" (Galacia 6:1)."
    ),
    insight: [
      t(
        "The word \"restore\" in Galatians 6:1 was used for setting a broken bone or mending a net. The goal of correction is never to win, to punish or to prove we are right; it is to heal. If you cannot honestly say, \"I want this person restored,\" you are not ready to speak. Notice too the hidden condition: \"you who are spiritual.\" Spiritual maturity is shown by the way we correct, not by how accurately.",
        "Ang salitang \"ibalik\" sa Galacia 6:1 ay ginagamit sa pag-aayos ng basag na buto o pagkukumpuni ng lambat. Ang layunin ng pagtutuwid ay hindi manalo, magparusa o patunayang tama tayo; ito ay magpagaling. Kung hindi mo matapat na masabing, \"Gusto kong maibalik ang taong ito,\" hindi ka pa handang magsalita. Pansinin din ang nakatagong kondisyon: \"kayong mga espirituwal.\" Ang pagkamaygulang sa espiritu ay ipinapakita ng paraan natin ng pagtutuwid, hindi ng pagiging tumpak lang."
      ),
      t(
        "Many leaders fall into one of two ditches: they avoid hard conversations to keep peace, or they confront with a harshness that crushes. Proverbs 27:6 says that a friend's wound is faithful, while an enemy's kisses are deceitful. Silence can be cowardice dressed as kindness. But Paul adds the safeguard: \"keep watch on yourself.\" The one who corrects must stay humble, aware that the same temptation could be his.",
        "Maraming lider ang nahuhulog sa isa sa dalawang hukay: umiiwas sa mahihirap na usapan para manatili ang kapayapaan, o nagko-confront nang may kabagsikang dumudurog. Sabi ng Kawikaan 27:6, tapat ang sugat ng kaibigan, ngunit mapanlinlang ang halik ng kaaway. Ang katahimikan ay maaaring duwag na nakadamit-kabaitan. Pero idinagdag ni Pablo ang pananggalang: \"bantayan ang sarili.\" Ang nagtutuwid ay dapat manatiling mapagpakumbaba, alam na maaaring pareho rin ang tuksong dumating sa kanya."
      ),
    ],
    life: [
      t(
        "Suppose you notice that a young brother in your group is secretly gambling online and borrowing money from friends. You can post a vague \"hint\" on social media, gossip with others, or avoid him. Or you can meet him privately after work, over coffee, and say, \"Kuya, I care about you, and I am worried. Can we talk about what is happening?\" Matthew 18:15 says to go to him alone first. Private, caring honesty protects both his dignity and the church.",
        "Halimbawa, napansin mong lihim palang nagsusugal online ang batang kapatid sa group mo at nangungutang sa mga kaibigan. Puwede kang mag-post ng malabong \"pasaring\" sa social media, makipagtsismisan, o umiwas sa kanya. O puwede mo siyang makausap nang pribado pagkatapos ng trabaho, habang nagkakape, at sabihing, \"Kuya, mahalaga ka sa akin, at nag-aalala ako. Puwede ba tayong mag-usap tungkol sa nangyayari?\" Sabi ng Mateo 18:15, puntahan muna siya nang mag-isa. Ang pribado at mapagmalasakit na katapatan ay nagpoprotekta sa dignidad niya at sa simbahan."
      ),
      t(
        "Before correcting, pray, check your own heart, gather facts, choose a good time and place, start with affirmation, speak specifically, ask questions, and offer to walk with the person. After you speak, give grace and time. Not everyone responds immediately; the Lord is the One who grants repentance (2 Timothy 2:25).",
        "Bago magtuwid, manalangin, suriin ang sariling puso, alamin ang katotohanan, pumili ng magandang oras at lugar, magsimula sa pagpapatibay, magsalita nang tiyak, magtanong, at mag-alok na samahan ang tao. Pagkatapos magsalita, magbigay ng biyaya at panahon. Hindi lahat ay agad tumutugon; ang Panginoon ang nagkakaloob ng pagsisisi (2 Timoteo 2:25)."
      ),
    ],
    twist: t(
      "We think gentleness weakens the message. The Kingdom twist is that gentleness makes the message heard. \"A soft tongue will break a bone\" (Proverbs 25:15). Nathan did not storm into David's palace; he told a story, and the king condemned himself (2 Samuel 12:1-7). Harshness makes people defend themselves; gentleness lowers the defenses so that truth can enter.",
      "Akala natin pinahihina ng kahinahunan ang mensahe. Ang twist ng Kaharian: ang kahinahunan ang nagpapadinig sa mensahe. \"Ang malambot na dila ay nakababali ng buto\" (Kawikaan 25:15). Hindi nagwala si Natan sa palasyo ni David; nagkuwento siya, at ang hari mismo ang humatol sa sarili (2 Samuel 12:1-7). Ang kabagsikan ay nagpapadepensa sa tao; ang kahinahunan ay nagpapababa ng depensa upang makapasok ang katotohanan."
    ),
    confirm: [
      t("Matthew 18:15-17: go to your brother privately first, then involve others only if needed.", "Mateo 18:15-17: puntahan muna ang kapatid nang pribado, saka lang isama ang iba kung kailangan."),
      t("Ephesians 4:15: speak the truth in love and grow up in every way into Christ.", "Efeso 4:15: sabihin ang katotohanan sa pag-ibig at lumago sa lahat ng bagay kay Cristo."),
      t("Galatians 2:11-14: Paul corrected Peter when his conduct did not match the gospel.", "Galacia 2:11-14: itinuwid ni Pablo si Pedro nang hindi tugma sa ebanghelyo ang kilos nito."),
      t("Psalm 141:5: let a righteous man strike me; it is a kindness.", "Awit 141:5: hayaang hampasin ako ng matuwid; kabutihan iyon."),
    ],
    heart: [
      t(
        "Examine your motive before you speak. If it is irritation, pride or the wish to be right, wait and pray until love is the reason.",
        "Suriin ang motibo bago magsalita. Kung inis, pride o gustong tama, maghintay at manalangin hanggang ang pag-ibig na ang dahilan."
      ),
      t(
        "Be a leader who can also be corrected. Invite honest words about yourself, and thank the one who dares to speak them.",
        "Maging lider na kayang itama rin. Anyayahan ang tapat na salita tungkol sa iyo, at pasalamatan ang may lakas-loob magsabi nito."
      ),
    ],
    questions: [
      t("Is there someone I need to speak to but have been avoiding?", "May tao ba akong dapat kausapin pero iniiwasan ko?"),
      t("When I have corrected people before, was I trying to restore them or to be right?", "Noong nagtuwid ako ng tao dati, sinusubukan ko ba silang ibalik o ang mapatunayang tama ako?"),
      t("Do I have anyone in my life who is allowed to correct me?", "May tao ba sa buhay ko na pinapayagan kong magtuwid sa akin?"),
      t("What does Galatians 6:1 teach me about my own weakness?", "Ano ang itinuturo ng Galacia 6:1 tungkol sa sarili kong kahinaan?"),
    ],
    actions: [
      t("Pray over the person you need to speak to, and ask God for the right words and the right moment.", "Ipanalangin ang taong kailangan mong kausapin, at hilingin sa Diyos ang tamang salita at tamang sandali."),
      t("Prepare one sentence of genuine encouragement and one caring question to open the conversation.", "Maghanda ng isang pangungusap ng tunay na pampalakas-loob at isang mapagmalasakit na tanong para simulan ang usapan."),
      t("Ask a trusted friend to give you honest feedback this week, and receive it without defending yourself.", "Humingi ng tapat na puna sa mapagkakatiwalaang kaibigan ngayong linggo, at tanggapin ito nang hindi nagtatanggol."),
    ],
    prayer: t(
      "Lord, give me courage to speak the truth and gentleness to speak it well. Search my heart for pride, impatience and the wish to be right. Make me like a friend whose wounds are faithful, who restores rather than crushes. Keep me watchful over my own weakness. Soften the hearts of those I need to speak with, and grant them repentance that leads to freedom. Teach me to receive correction as well. Let my words heal. In Jesus' name, Amen.",
      "Panginoon, bigyan Mo ako ng tapang na sabihin ang katotohanan at kahinahunang sabihin ito nang maayos. Siyasatin Mo ang puso ko para sa pride, kawalan ng pasensiya at gustong tama ako. Gawin Mo akong gaya ng kaibigang tapat ang mga sugat, na nagbabalik at hindi dumudurog. Panatilihin Mo akong mapagbantay sa sarili kong kahinaan. Palambutin Mo ang puso ng mga taong kailangan kong kausapin, at ipagkaloob Mo sa kanila ang pagsisising umaakay sa kalayaan. Turuan Mo rin akong tumanggap ng pagtutuwid. Hayaang magpagaling ang aking mga salita. Sa pangalan ni Hesus, Amen."
    ),
  },
  "discipling-the-next-generation": {
    revelation: t(
      "The faith of the next generation is rarely passed on by programs; it is caught from the lives and stories of those who love Jesus in front of them.",
      "Bihirang maipasa ang pananampalataya ng susunod na henerasyon sa pamamagitan ng programa; nahuhuli ito mula sa buhay at kuwento ng mga nagmamahal kay Hesus sa harap nila."
    ),
    mainTruth: t(
      "\"We will not hide them from their children, but tell to the coming generation the glorious deeds of the Lord, and his might, and the wonders that he has done... so that the next generation might know them, the children yet unborn, and arise and tell them to their children, so that they should set their hope in God\" (Psalm 78:4-7). Paul reminds Timothy of the \"sincere faith\" that lived first in his grandmother Lois and his mother Eunice (2 Timothy 1:5). And \"Train up a child in the way he should go; even when he is old he will not depart from it\" (Proverbs 22:6).",
      "\"Hindi namin itatago sa kanilang mga anak, kundi sasabihin sa darating na salinlahi ang maluwalhating gawa ng Panginoon, ang Kanyang lakas, at ang mga kababalaghang ginawa Niya... upang makilala sila ng susunod na salinlahi, ng mga batang hindi pa ipinapanganak, at tumindig sila at ikuwento ito sa kanilang mga anak, upang ang pag-asa nila ay mailagay sa Diyos\" (Awit 78:4-7). Ipinaalala ni Pablo kay Timoteo ang \"tapat na pananampalataya\" na unang nanahan sa lola niyang si Loida at sa inang si Eunice (2 Timoteo 1:5). At \"Turuan mo ang bata sa daang dapat niyang lakaran; kahit matanda na siya ay hindi niya ito lilisanin\" (Kawikaan 22:6)."
    ),
    insight: [
      t(
        "Notice what Psalm 78 says should be passed down: not rules alone, but the deeds of the Lord, stories of what God has done. Children can resist a lecture, but they lean in when someone says, \"Let me tell you how God brought us through.\" Faith is more caught than taught. Timothy's faith was first lived by two women before it was ever preached by Paul.",
        "Pansinin kung ano ang sinasabi ng Awit 78 na dapat ipasa: hindi lang mga patakaran, kundi ang mga gawa ng Panginoon, ang mga kuwento ng ginawa ng Diyos. Puwedeng tumutol ang bata sa sermon, pero sumisiksik siya kapag may nagsasabing, \"Ikukuwento ko kung paano tayo dinala ng Diyos.\" Mas nahuhuli kaysa naituturo ang pananampalataya. Ang pananampalataya ni Timoteo ay unang isinabuhay ng dalawang babae bago pa ito ipinangaral ni Pablo."
      ),
      t(
        "Proverbs 22:6 is a principle, not an unbreakable promise; children still have their own choices. But it does tell us that early, steady, loving training shapes a person's direction. \"In the way he should go\" implies knowing each child's temperament. Discipling a young person is not about control. It is about walking beside them until they can walk with God on their own.",
        "Ang Kawikaan 22:6 ay simulain, hindi hindi-nababaling pangako; may sarili pa ring pagpili ang mga bata. Pero sinasabi nitong ang maaga, tuluy-tuloy at mapagmahal na pagsasanay ay humuhubog sa direksyon ng tao. Ang \"sa daang dapat niyang lakaran\" ay nagpapahiwatig ng pag-alam sa ugali ng bawat bata. Ang pagdidisipulo sa kabataan ay hindi pagkontrol. Ito ay paglalakad sa tabi nila hanggang sa kaya na nilang lumakad kasama ng Diyos nang mag-isa."
      ),
    ],
    life: [
      t(
        "Think of a lola in a small barrio, praying simple prayers each evening for her apo, and telling stories of how God provided in lean years. Her grandchild grows up, goes abroad, and in a lonely night in a foreign city remembers Lola's voice saying, \"Huwag kang bibitiw sa Diyos.\" One quiet life of faith became a lifeline across oceans.",
        "Isipin ang isang lola sa maliit na baryo, na gabi-gabing nananalangin nang simple para sa kanyang apo, at nagkukuwento kung paano nagbigay ang Diyos noong panahon ng kapos. Lumaki ang apo, nagtrabaho sa abroad, at sa isang malungkot na gabi sa banyagang lungsod ay naalala ang tinig ni Lola na nagsasabing, \"Huwag kang bibitiw sa Diyos.\" Ang isang tahimik na buhay ng pananampalataya ay naging lifeline sa kabilang dagat."
      ),
      t(
        "For OFW parents whose children are growing up through video calls, discipleship is still possible: pray together over the phone, read one verse by chat, tell your children your faith stories, and support the relative or church leader who is with them. For youth leaders, listen more than you lecture, be present at their games and exams, and let them ask hard questions without fear.",
        "Para sa mga OFW na magulang na ang mga anak ay lumalaki sa video call, posible pa ring magdisipulo: magdasal nang magkasama sa telepono, magbasa ng isang talata sa chat, ikuwento sa mga anak ang mga kuwento ng pananampalataya mo, at suportahan ang kamag-anak o lider ng simbahan na kasama nila. Para sa mga youth leader, making nang higit sa pagsesermon, dumalo sa mga laro at pagsusulit nila, at hayaan silang magtanong ng mahihirap na tanong nang walang takot."
      ),
    ],
    twist: t(
      "We often think the church ministers to children. The Kingdom twist is that Jesus put a child in the middle and said we must become like them to enter the kingdom (Matthew 18:2-4). The next generation is not only a group to be taught; they are also teachers of simple trust, wonder and forgiveness. Disciple them and you will be discipled.",
      "Madalas nating isipin na ang simbahan ang naglilingkod sa mga bata. Ang twist ng Kaharian: inilagay ni Hesus ang isang bata sa gitna at sinabing kailangan nating maging tulad nila para makapasok sa kaharian (Mateo 18:2-4). Ang susunod na henerasyon ay hindi lang grupong tuturuan; sila rin ay guro ng simpleng pagtitiwala, pagkamangha at pagpapatawad. Disipulohin mo sila at madidisipulo ka."
    ),
    confirm: [
      t("Deuteronomy 6:6-7: impress God's words on your children when you sit, walk, lie down and rise.", "Deuteronomio 6:6-7: ituro nang paulit-ulit ang mga salita ng Diyos sa mga anak kapag nakaupo, naglalakad, nahihiga at bumabangon."),
      t("Mark 10:13-16: Jesus welcomed the children and blessed them.", "Marcos 10:13-16: tinanggap at pinagpala ni Hesus ang mga bata."),
      t("1 Samuel 3:1-10: young Samuel heard God's voice with the guidance of Eli.", "1 Samuel 3:1-10: narinig ng batang si Samuel ang tinig ng Diyos sa gabay ni Eli."),
      t("Ephesians 6:4: fathers, do not provoke your children, but bring them up in the discipline and instruction of the Lord.", "Efeso 6:4: mga ama, huwag ninyong galitin ang inyong mga anak, kundi palakihin sila sa disiplina at aral ng Panginoon."),
    ],
    heart: [
      t(
        "Live what you hope they will believe. Let them see you pray, say sorry, forgive and trust God when it is hard.",
        "Isabuhay ang inaasahan mong paniwalaan nila. Hayaan silang makita kang nananalangin, humihingi ng tawad, nagpapatawad at nagtitiwala sa Diyos kapag mahirap."
      ),
      t(
        "Be patient with their questions and their seasons of doubt. Love them as Jesus does, and entrust them to God's care, even when they wander.",
        "Magtiyaga sa mga tanong nila at sa mga panahon ng duda. Mahalin sila gaya ng pagmamahal ni Hesus, at ipagkatiwala sa Diyos, kahit lumayo sila."
      ),
    ],
    questions: [
      t("Which young person has God placed near me, in my family, church or neighborhood?", "Sinong kabataan ang inilagay ng Diyos malapit sa akin, sa pamilya, simbahan o kapitbahayan?"),
      t("Do they know my faith stories, or only my rules?", "Alam ba nila ang mga kuwento ng pananampalataya ko, o mga patakaran ko lang?"),
      t("Is my home a safe place to ask hard questions about God?", "Ligtas bang lugar ang bahay ko para magtanong ng mahihirap na tanong tungkol sa Diyos?"),
      t("Am I praying for the next generation regularly and by name?", "Ipinapanalangin ko ba nang regular at may pangalan ang susunod na henerasyon?"),
    ],
    actions: [
      t("Share one story this week of how God helped you, with a child or young person.", "Magbahagi ngayong linggo ng isang kuwento kung paano ka tinulungan ng Diyos, sa isang bata o kabataan."),
      t("Pray with a child or teenager, in person or by video call, and let them pray too.", "Manalangin kasama ang bata o tinedyer, personal man o video call, at hayaan din silang manalangin."),
      t("Ask a young person what they are learning or struggling with, and simply listen without correcting.", "Tanungin ang isang kabataan kung ano ang natututunan o pinagdadaanan niya, at making lang nang hindi nagtatama."),
    ],
    prayer: t(
      "Lord, thank You for those who passed their faith on to me. Make me a faithful link in that chain. Help me to tell the next generation of Your glorious deeds, not only with words but with a life that shows You are real. Protect the children and young people around me. Draw them to Jesus, and keep them from the lies of this world. Give me patience, wisdom and love. Let them set their hope in You. In Jesus' name, Amen.",
      "Panginoon, salamat sa mga nagpasa sa akin ng pananampalataya. Gawin Mo akong tapat na kawing sa tanikalang iyon. Tulungan Mo akong ikuwento sa susunod na henerasyon ang Iyong maluwalhating gawa, hindi lang sa salita kundi sa buhay na nagpapakitang totoo Ka. Ingatan Mo ang mga bata at kabataan sa paligid ko. Ilapit Mo sila kay Hesus, at ilayo sa mga kasinungalingan ng mundo. Bigyan Mo ako ng pasensiya, karunungan at pag-ibig. Hayaan Mong sa Iyo mailagay ang kanilang pag-asa. Sa pangalan ni Hesus, Amen."
    ),
  },
  "whole-households": {
    revelation: t(
      "When the gospel enters one heart, God's desire is that it flows through the whole household, and your home can become a mission field and a church.",
      "Kapag pumasok ang ebanghelyo sa isang puso, nais ng Diyos na dumaloy ito sa buong sambahayan, at ang tahanan mo ay puwedeng maging mission field at simbahan."
    ),
    mainTruth: t(
      "At midnight in prison, Paul and Silas prayed and sang, and an earthquake opened the doors. The jailer asked, \"What must I do to be saved?\" and they answered, \"Believe in the Lord Jesus, and you will be saved, you and your household\" (Acts 16:25-34). The jailer washed their wounds, was baptized with all his family, and rejoiced with his whole house. Cornelius likewise gathered his relatives and close friends to hear Peter, and the Holy Spirit fell on all who heard (Acts 10:24-27, 44-48).",
      "Sa hatinggabi sa bilangguan, nanalangin at umawit sina Pablo at Silas, at binuksan ng lindol ang mga pinto. Nagtanong ang bantay, \"Ano ang dapat kong gawin upang maligtas?\" at sumagot sila, \"Sumampalataya ka sa Panginoong Hesus, at maliligtas ka, ikaw at ang iyong sambahayan\" (Gawa 16:25-34). Hinugasan ng bantay ang kanilang mga sugat, nabautismuhan siya kasama ang buong pamilya, at nagalak sila ng buong sambahayan. Gayundin, tinipon ni Cornelio ang mga kamag-anak at malalapit na kaibigan para pakinggan si Pedro, at bumaba ang Banal na Espiritu sa lahat ng nakinig (Gawa 10:24-27, 44-48)."
    ),
    insight: [
      t(
        "In the Bible world, a household was more than parents and children: it included extended family, servants, workers and friends living together. When the head of the home believed, the home became the natural place for the gospel to spread. This is very close to Filipino culture, where family, kamag-anak and kapitbahay are tightly woven. God is not asking us to leave our relationships; He wants to redeem them.",
        "Sa mundo ng Bibliya, ang sambahayan ay higit pa sa magulang at anak: kasama ang malawak na pamilya, utusan, manggagawa at kaibigang magkakasamang nakatira. Kapag naniwala ang puno ng tahanan, natural na lugar ang tahanan para kumalat ang ebanghelyo. Napakalapit nito sa kulturang Pilipino kung saan magkakabit ang pamilya, kamag-anak at kapitbahay. Hindi hinihiling ng Diyos na iwan natin ang ating mga relasyon; nais Niyang tubusin ang mga ito."
      ),
      t(
        "Notice what opened the jailer's household: Paul and Silas worshiped in pain, and the jailer saw something real. They did not preach a clever sermon first; they showed a different spirit. Then, once the jailer was open, they spoke the Word \"to him and to all who were in his house\" (Acts 16:32). The sequence is witness, word, welcome. Faith does not skip the home; it starts there.",
        "Pansinin kung ano ang nagbukas sa sambahayan ng bantay: sumamba sina Pablo at Silas sa gitna ng sakit, at may nakita siyang totoo. Hindi sila nagsermon muna nang matalino; ipinakita nila ang ibang espiritu. Pagkatapos, nang bukas na ang bantay, ipinahayag nila ang Salita \"sa kanya at sa lahat ng nasa kanyang bahay\" (Gawa 16:32). Ang daloy ay patotoo, salita, pagtanggap. Hindi nilalaktawan ng pananampalataya ang tahanan; doon ito nagsisimula."
      ),
    ],
    life: [
      t(
        "Imagine a mother in the family who comes to know Jesus while working abroad. She does not return home with a lecture; she calls her family with joy, prays for her husband by name, sends a Bible app link to her teenager, and asks her sister to host a simple Bible sharing in the living room when she is home on vacation. Within a year, three relatives join the Sunday gathering. Her home became a doorway.",
        "Isipin ang isang nanay sa pamilya na nakilala si Hesus habang nagtatrabaho sa abroad. Hindi siya umuuwi na may sermon; tumatawag siya sa pamilya nang may galak, ipinapanalangin ang asawa sa pangalan, nagpapadala ng link ng Bible app sa tinedyer niyang anak, at hinihiling sa kapatid na mag-host ng simpleng Bible sharing sa sala kapag nakauwi siya sa bakasyon. Sa loob ng isang taon, tatlong kamag-anak ang sumama sa Sunday gathering. Ang bahay niya ay naging pintuan."
      ),
      t(
        "Be careful and wise, though. Do not pressure or shame relatives who are not ready. Love shows through service: cooking, helping with bills, listening. Invite them to meals and to the good things you enjoy with God. Pray for the \"man of peace\" in each household (Luke 10:5-7), the one whose heart is open, and begin there.",
        "Mag-ingat at maging marunong din. Huwag pilitin o ipahiya ang mga kamag-anak na hindi pa handa. Ipinapakita ang pag-ibig sa paglilingkod: pagluluto, pagtulong sa bayarin, pakikinig. Anyayahan sila sa pagkain at sa magagandang bagay na tinatamasa mo kasama ng Diyos. Ipanalangin ang \"taong mapayapa\" sa bawat sambahayan (Lucas 10:5-7), ang bukas ang puso, at doon magsimula."
      ),
    ],
    twist: t(
      "We think evangelism means leaving home to reach strangers. The Kingdom twist is that the first and strongest mission field is the one you sleep in. Jesus told the healed man of Gadara, \"Go home to your own people and tell them how much the Lord has done for you\" (Mark 5:19). Home is not a break from ministry; it is the hardest and most fruitful one.",
      "Akala natin ang pagpapahayag ay paglabas ng bahay para abutin ang mga estranghero. Ang twist ng Kaharian: ang una at pinakamatibay na mission field ay ang tinutulugan mo. Sinabi ni Hesus sa pinagaling na lalaki sa Gadara, \"Umuwi ka sa iyong mga kasambahay at ibalita mo kung gaano karami ang ginawa ng Panginoon para sa iyo\" (Marcos 5:19). Ang tahanan ay hindi pahinga sa ministeryo; ito ang pinakamahirap at pinakamabungang ministeryo."
    ),
    confirm: [
      t("Acts 18:8: Crispus, the synagogue ruler, believed in the Lord together with his entire household.", "Gawa 18:8: sumampalataya sa Panginoon si Crispo, ang pinuno ng sinagoga, kasama ang buo niyang sambahayan."),
      t("Joshua 24:15: \"As for me and my house, we will serve the Lord.\"", "Josue 24:15: \"Ngunit ako at ang aking sambahayan ay maglilingkod sa Panginoon.\""),
      t("1 Peter 3:1-2: wives can win their husbands without a word by their respectful, pure conduct.", "1 Pedro 3:1-2: maaaring maakit ng mga asawang babae ang kanilang mga asawa nang walang salita sa pamamagitan ng magalang at malinis na asal."),
      t("Colossians 4:15: the church met in Nympha's house.", "Colosas 4:15: nagtitipon ang iglesia sa bahay ni Nimfa."),
    ],
    heart: [
      t(
        "See your household as people God loves, not as projects. Love them before you try to convince them, and keep loving them when they resist.",
        "Tingnan ang sambahayan mo bilang mga taong mahal ng Diyos, hindi proyekto. Mahalin sila bago mo subukang kumbinsihin, at patuloy na mahalin kapag lumalaban sila."
      ),
      t(
        "Make your home a place where Jesus is welcome: prayer at meals, Scripture in the open, worship music, hospitality for the lonely.",
        "Gawing tahanan ang bahay kung saan welcome si Hesus: dasal sa pagkain, Kasulatan sa harap, awit ng pagsamba, pagpapatuloy sa mga nalulungkot."
      ),
    ],
    questions: [
      t("Who in my household does not know Jesus yet, and am I praying for them daily?", "Sino sa sambahayan ko ang hindi pa nakakakilala kay Hesus, at ipinapanalangin ko ba sila araw-araw?"),
      t("Does my daily life make Jesus attractive to the people I live or work with?", "Ginagawa bang kaakit-akit si Hesus ng pang-araw-araw kong buhay para sa mga kasama ko sa bahay o trabaho?"),
      t("Who is the \"man of peace\" in my family or neighborhood who may be open?", "Sino ang \"taong mapayapa\" sa pamilya o kapitbahayan ko na maaaring bukas?"),
      t("What small step could turn my home into a place of prayer and welcome?", "Anong maliit na hakbang ang makapagpapalit sa tahanan ko bilang lugar ng panalangin at pagtanggap?"),
    ],
    actions: [
      t("List the names of your household and extended family, and pray for each one this week.", "Ilista ang pangalan ng sambahayan at malawak mong pamilya, at ipanalangin ang bawat isa ngayong linggo."),
      t("Start or restore a short family prayer time, even five minutes a day, in person or by call.", "Magsimula o ibalik ang maikling oras ng panalangin ng pamilya, kahit limang minuto sa isang araw, personal man o tawag."),
      t("Invite one relative or neighbor to a meal or a gathering, with no pressure, just love.", "Mag-imbita ng isang kamag-anak o kapitbahay sa pagkain o pagtitipon, walang pamimilit, pag-ibig lang."),
    ],
    prayer: t(
      "Father, I lift up my household to You. You know every name and every heart. Open the eyes of those who do not yet know Jesus. Make my life a witness of Your peace, kindness and truth. Give me patience with those who resist, and wisdom to show love in practical ways. Let my home be a place where Your Spirit is welcome, and where Your Word is spoken. Save my family, and use us to bless our neighbors. In Jesus' name, Amen.",
      "Ama, itinataas ko sa Iyo ang aking sambahayan. Alam Mo ang bawat pangalan at bawat puso. Imulat Mo ang mga mata ng mga hindi pa nakakakilala kay Hesus. Gawin Mong patotoo ng Iyong kapayapaan, kabaitan at katotohanan ang buhay ko. Bigyan Mo ako ng pasensiya sa mga lumalaban, at karunungang magpakita ng pag-ibig sa praktikal na paraan. Hayaang maging lugar ang tahanan ko kung saan welcome ang Iyong Espiritu at sinasabi ang Iyong Salita. Iligtas Mo ang pamilya ko, at gamitin Mo kami upang maging pagpapala sa mga kapitbahay. Sa pangalan ni Hesus, Amen."
    ),
  },
  "answering-with-gentleness": {
    revelation: t(
      "People are rarely won by the person who wins the argument; they are won by the person whose gentleness makes them curious about the hope inside.",
      "Bihirang makuha ang tao ng nananalo sa debate; nakukuha sila ng taong ang kahinahunan ay nagpapausisa sa kanila tungkol sa pag-asang nasa loob."
    ),
    mainTruth: t(
      "Paul went into the synagogue at Thessalonica and for three Sabbaths \"reasoned with them from the Scriptures, explaining and proving that the Christ had to suffer and rise from the dead\" (Acts 17:1-3), and some were persuaded. Colossians 4:5-6 says, \"Walk in wisdom toward outsiders, making the best use of the time. Let your speech always be gracious, seasoned with salt, so that you may know how you ought to answer each person.\" Jude urges us to \"contend for the faith that was once for all delivered to the saints\" (Jude 1:3), and Peter adds that we should do so with gentleness and respect (1 Peter 3:15).",
      "Pumasok si Pablo sa sinagoga sa Tesalonica at sa loob ng tatlong Sabbath ay \"nangatuwiran sa kanila mula sa Kasulatan, ipinaliliwanag at pinatutunayan na kailangang magdusa at muling mabuhay si Cristo\" (Gawa 17:1-3), at may mga nahikayat. Sabi ng Colosas 4:5-6, \"Lumakad kayo nang may karunungan sa mga nasa labas, at samantalahin ang panahon. Laging maging mabiyaya ang inyong pananalita, may kasamang asin, upang malaman ninyo kung paano sumagot sa bawat tao.\" Hinihimok tayo ni Judas na \"ipaglaban ang pananampalatayang minsan at magpakailanmang ipinagkatiwala sa mga banal\" (Judas 1:3), at idinagdag ni Pedro na gawin ito nang may kahinahunan at paggalang (1 Pedro 3:15)."
    ),
    insight: [
      t(
        "Notice that Paul reasoned, explained and proved, using Scripture. Faith is not blind; we are allowed to think and to give good answers. But also notice the tone Colossians demands: grace and salt. Grace makes the words welcome; salt makes them meaningful. Answers delivered with contempt may be correct but will never persuade. Truth wrapped in arrogance is often rejected for the wrapper.",
        "Pansinin na nangatuwiran, nagpaliwanag at nagpatunay si Pablo gamit ang Kasulatan. Hindi bulag ang pananampalataya; pinapayagan tayong mag-isip at magbigay ng mahusay na sagot. Pero pansinin din ang tono na hinihingi ng Colosas: biyaya at asin. Ang biyaya ang nagpapa-welcome sa salita; ang asin ang nagbibigay ng kahulugan. Ang sagot na may paghamak ay maaaring tama pero hindi kailanman makahihikayat. Ang katotohanang nakabalot sa kayabangan ay madalas tinatanggihan dahil sa balot."
      ),
      t(
        "\"Know how you ought to answer each person\" means that people are different. The Muslim coworker, the skeptical engineer, the Catholic relative, the lapsed friend each carry different questions and wounds. A good answer begins with a good question and a listening heart. Jesus rarely answered a question without first learning what was behind it. And it is perfectly fine to say, \"I do not know; let me find out.\"",
        "Ang \"alamin kung paano sumagot sa bawat tao\" ay nangangahulugang magkakaiba ang mga tao. Ang katrabahong Muslim, ang duda-dudang engineer, ang kamag-anak na Katoliko, ang kaibigang lumayo, bawat isa ay may sariling tanong at sugat. Ang mahusay na sagot ay nagsisimula sa mahusay na tanong at pusong nakikinig. Bihirang sumagot si Hesus sa tanong nang hindi muna inaalam ang nasa likod nito. At ayos lang na sabihing, \"Hindi ko alam; aalamin ko.\""
      ),
    ],
    life: [
      t(
        "Imagine an OFW nurse working in a hospital in a country where Christianity is a minority. A colleague asks, \"Why do you believe in a God who let your friend die?\" She could argue, panic or go quiet. Instead she says softly, \"That is a hard question, and I have asked it too. Can I tell you what has held me?\" She answers with her story, one or two verses, and no pressure. The colleague does not convert that day, but she asks another question next week.",
        "Isipin ang isang OFW na nars sa ospital sa bansang minorya ang Kristiyano. Tinanong siya ng katrabaho, \"Bakit ka naniniwala sa Diyos na hinayaang mamatay ang kaibigan mo?\" Puwede siyang makipagtalo, mataranta o manahimik. Sa halip mahina niyang sinabi, \"Mahirap na tanong iyan, at itinanong ko rin ito. Puwede ko bang ikuwento kung ano ang nagpapatatag sa akin?\" Sinagot niya ng kuwento niya, isa o dalawang talata, at walang pamimilit. Hindi nagbago ng pananampalataya ang katrabaho nang araw na iyon, pero nagtanong ulit siya sa susunod na linggo."
      ),
      t(
        "In areas where open evangelism is restricted, wisdom is especially needed. Respect local laws and your employer's rules, rely on relationship and conduct, and let people ask first. \"Always be prepared\" means to be ready to answer, not to start fights. Online, resist the urge to win comment-section wars. Few people were ever convinced by an angry post.",
        "Sa mga lugar na may limitasyon ang hayagang pagpapahayag, lalong kailangan ang karunungan. Igalang ang batas ng lugar at patakaran ng amo, umasa sa ugnayan at asal, at hayaang sila ang magtanong muna. Ang \"laging maging handa\" ay ang pagiging handang sumagot, hindi ang pagsisimula ng away. Online, labanan ang tuksong manalo sa comment section. Kakaunting tao ang nakumbinse ng galit na post."
      ),
    ],
    twist: t(
      "We believe a strong defense of the faith needs a strong voice. The Kingdom twist is that the strongest apologetic is a transformed, gentle life. Jesus said, \"By this all people will know that you are my disciples, if you have love for one another\" (John 13:35). Arguments may open the mind, but love opens the heart, and the heart is the place where people actually decide.",
      "Akala natin ang matibay na pagtatanggol sa pananampalataya ay nangangailangan ng malakas na boses. Ang twist ng Kaharian: ang pinakamatibay na patunay ay ang nabagong at mahinahong buhay. Sabi ni Hesus, \"Sa pamamagitan nito'y makikilala ng lahat na kayo'y Aking mga alagad, kung may pag-ibig kayo sa isa't isa\" (Juan 13:35). Maaaring buksan ng argumento ang isip, pero ang pag-ibig ang nagbubukas ng puso, at ang puso ang lugar kung saan talaga nagpapasya ang tao."
    ),
    confirm: [
      t("1 Peter 3:15: always be prepared to give an answer for the hope you have, with gentleness and respect.", "1 Pedro 3:15: laging maging handang sumagot tungkol sa pag-asang taglay ninyo, nang may kahinahunan at paggalang."),
      t("Acts 17:22-31: Paul began with the Athenians' own altar and poets before proclaiming Christ.", "Gawa 17:22-31: nagsimula si Pablo sa mismong altar at makata ng mga taga-Atenas bago ipahayag si Cristo."),
      t("Proverbs 15:1: a soft answer turns away wrath.", "Kawikaan 15:1: ang malumanay na sagot ay pumapawi ng poot."),
      t("2 Timothy 2:23-24: avoid foolish controversies; the Lord's servant must not be quarrelsome.", "2 Timoteo 2:23-24: iwasan ang mga mangmang na pagtatalo; ang lingkod ng Panginoon ay hindi dapat palaaway."),
    ],
    heart: [
      t(
        "Choose to love the person more than the argument. Remember that the goal is that they would meet Jesus, not that you would feel clever.",
        "Piliin mong mahalin ang tao nang higit sa argumento. Tandaang ang layunin ay makilala nila si Hesus, hindi na pakiramdam mong matalino ka."
      ),
      t(
        "Do the hard work of learning. Study your faith so that you can speak with clarity, and stay humble enough to say \"I do not know.\"",
        "Gawin ang mahirap na pag-aaral. Pag-aralan ang pananampalataya mo upang makapagsalita nang malinaw, at manatiling mapagpakumbaba para masabing \"Hindi ko alam.\""
      ),
    ],
    questions: [
      t("Do I tend to avoid questions about my faith, or to argue too hard?", "Madalas ba akong umiwas sa mga tanong tungkol sa pananampalataya ko, o makipagtalo nang sobra?"),
      t("Can I explain in simple words why I trust Jesus?", "Maipapaliwanag ko ba sa simpleng salita kung bakit ako nagtitiwala kay Hesus?"),
      t("Who in my life is asking questions that I could answer with patience?", "Sino sa buhay ko ang may mga tanong na masasagot ko nang may pasensiya?"),
      t("Is my online and offline speech about faith gracious and salty?", "Mabiyaya at may asin ba ang pananalita ko tungkol sa pananampalataya, online man o offline?"),
    ],
    actions: [
      t("Write a two-minute answer to \"Why do you follow Jesus?\" and practice saying it aloud.", "Sumulat ng dalawang-minutong sagot sa \"Bakit ka sumusunod kay Hesus?\" at magsanay sabihin ito nang malakas."),
      t("Ask a friend who doubts what their biggest question about God is, and listen without interrupting.", "Tanungin ang kaibigang nagdududa kung ano ang pinakamalaki niyang tanong tungkol sa Diyos, at making nang hindi sumisingit."),
      t("Pick one common objection and spend time this week studying a good answer from Scripture.", "Pumili ng isang karaniwang pagtutol at maglaan ng oras ngayong linggo sa pag-aaral ng mahusay na sagot mula sa Kasulatan."),
    ],
    prayer: t(
      "Lord Jesus, make me ready to give an answer for the hope in me. Give me wisdom to know what to say and when to stay silent. Season my words with grace and salt. Keep me from pride and from fear. Help me to love the people who question, doubt or mock, and to listen as You listen. Use my life and my words to open hearts to You. Where I do not have answers, make me humble enough to say so. In Your name, Amen.",
      "Panginoong Hesus, gawin Mo akong handang sumagot tungkol sa pag-asang nasa akin. Bigyan Mo ako ng karunungang malaman ang sasabihin at kung kailan tatahimik. Timplahan Mo ng biyaya at asin ang aking mga salita. Ilayo Mo ako sa pride at sa takot. Tulungan Mo akong mahalin ang mga nagtatanong, nagdududa o nanunuya, at making gaya ng pakikinig Mo. Gamitin Mo ang buhay at salita ko upang buksan ang mga puso sa Iyo. Kung saan wala akong sagot, gawin Mo akong mapagpakumbabang aminin ito. Sa pangalan Mo, Amen."
    ),
  },
  "praying-for-healing-and-freedom": {
    revelation: t(
      "Jesus still brings good news to the poor, freedom to captives and healing to the broken, and He invites ordinary believers to pray with faith and compassion.",
      "Nagdadala pa rin si Hesus ng mabuting balita sa mahihirap, kalayaan sa mga bihag at kagalingan sa mga sugatan, at inaanyayahan Niya ang karaniwang mananampalataya na manalangin nang may pananampalataya at habag."
    ),
    mainTruth: t(
      "In Nazareth Jesus read, \"The Spirit of the Lord is upon me, because he has anointed me to proclaim good news to the poor... to proclaim liberty to the captives and recovering of sight to the blind, to set at liberty those who are oppressed\" (Luke 4:18-19). Peter and John met a lame man at the temple gate: \"I have no silver and gold, but what I do have I give to you. In the name of Jesus Christ of Nazareth, rise up and walk!\" (Acts 3:1-10). James instructs the sick to call the elders to pray and anoint with oil in the name of the Lord, and to confess sins to one another and pray, \"that you may be healed\" (James 5:14-16).",
      "Sa Nazaret, binasa ni Hesus, \"Ang Espiritu ng Panginoon ay nasa Akin, sapagkat pinahiran Niya Ako upang ipangaral ang mabuting balita sa mga mahihirap... upang ipahayag ang kalayaan sa mga bihag at ang pagkakita sa mga bulag, upang palayain ang mga inaapi\" (Lucas 4:18-19). Nakasalubong nina Pedro at Juan ang pilay sa pintuan ng templo: \"Wala akong pilak at ginto, ngunit ang mayroon ako ay ibinibigay ko sa iyo. Sa pangalan ni Hesukristo na taga-Nazaret, bumangon ka at lumakad!\" (Gawa 3:1-10). Itinuturo ni Santiago na tawagin ng maysakit ang matatanda ng iglesia upang ipanalangin at pahiran ng langis sa pangalan ng Panginoon, at ipagtapat ang mga kasalanan sa isa't isa at manalangin, \"upang kayo ay gumaling\" (Santiago 5:14-16)."
    ),
    insight: [
      t(
        "Notice what Peter had: not silver or gold, but the name of Jesus. Prayer for healing is not a show of personal power; it is faith in the Person. We pray because Jesus is still compassionate and still able. At the same time, honest believers admit that not everyone is healed in the way and time we ask. Paul had a thorn that was not removed (2 Corinthians 12:7-9), and Timothy had frequent illnesses (1 Timothy 5:23). God heals, and He also sustains, so we pray with faith, without pretending to control outcomes.",
        "Pansinin kung ano ang mayroon si Pedro: hindi pilak o ginto, kundi ang pangalan ni Hesus. Ang panalangin para sa kagalingan ay hindi pagpapakita ng personal na kapangyarihan; ito ay pananampalataya sa Persona. Nananalangin tayo dahil mahabagin pa rin si Hesus at kaya pa rin Niya. Kasabay nito, inaamin ng mga tapat na mananampalataya na hindi lahat ay gumagaling sa paraan at oras na hinihiling natin. May tinik si Pablo na hindi inalis (2 Corinto 12:7-9), at madalas magkasakit si Timoteo (1 Timoteo 5:23). Nagpapagaling ang Diyos, at nag-aalalay rin Siya, kaya nananalangin tayo nang may pananampalataya, nang hindi nagkukunwaring kontrolado natin ang kalalabasan."
      ),
      t(
        "James connects healing with confession and community. Not all brokenness is in the body: shame, hidden sin, trauma, addiction, bitterness and fear also need healing and freedom. The elders, the oil, the confession and the prayer all happen in the open with others. Many are not set free because they carry their secret alone. Freedom often arrives when we bring what is hidden into safe, praying company.",
        "Iniuugnay ni Santiago ang kagalingan sa pagtatapat at pamayanan. Hindi lahat ng pagkasira ay nasa katawan: ang kahihiyan, lihim na kasalanan, trauma, adiksiyon, hinanakit at takot ay nangangailangan din ng kagalingan at kalayaan. Ang matatanda, ang langis, ang pagtatapat at ang panalangin ay lahat nangyayari sa harap ng iba. Maraming hindi pa napalalaya dahil mag-isa nilang dala ang kanilang lihim. Madalas dumarating ang kalayaan kapag dinadala natin ang nakatago sa ligtas at nananalangin na samahan."
      ),
    ],
    life: [
      t(
        "A co-worker tells you her mother back home has been diagnosed with a serious illness. You could say, \"I will pray for you,\" and walk away. Or you could ask, \"Can I pray with you right now?\" and, quietly, with her permission, ask Jesus to heal, to comfort and to be near. You do not need a loud voice, a special title or a formula. You need compassion and the name of Jesus. Afterwards, follow up with a message and a meal.",
        "Sinabi sa iyo ng katrabaho mong babae na na-diagnose ng malubhang sakit ang nanay niya sa Pilipinas. Puwede mong sabihing, \"Ipapanalangin kita,\" at umalis. O puwede mong itanong, \"Puwede ba kitang ipanalangin ngayon?\" at, nang tahimik, may pahintulot niya, hilingin kay Hesus na magpagaling, umaliw at lumapit. Hindi mo kailangan ng malakas na boses, espesyal na titulo o pormula. Kailangan mo ng habag at pangalan ni Hesus. Pagkatapos, magpadala ng mensahe at pagkain."
      ),
      t(
        "Praying for freedom works the same way: gentle, private and respectful. Listen first. Pray with Scripture, pray for forgiveness and for the Spirit's peace, and encourage the person to seek professional medical or counseling help as well. Prayer and doctors are not enemies. Never shame, never make promises God has not made, and never pressure someone to \"have more faith.\"",
        "Ganoon din ang panalangin para sa kalayaan: mahinahon, pribado at magalang. Making muna. Manalangin gamit ang Kasulatan, ipanalangin ang kapatawaran at kapayapaan ng Espiritu, at hikayatin ang tao na humingi rin ng propesyonal na tulong medikal o counseling. Hindi magkaaway ang panalangin at doktor. Huwag manghiya, huwag mangako ng hindi ipinangako ng Diyos, at huwag pilitin ang taong \"dagdagan pa ang pananampalataya.\""
      ),
    ],
    twist: t(
      "We think that the one who prays must be spiritually strong. The Kingdom twist is that the one who prays is often wounded too. Jesus is the Wounded Healer; \"by his wounds we are healed\" (Isaiah 53:5). Paul says God comforts us so that we can comfort others with the comfort we received (2 Corinthians 1:4). Our own healing journey is not a disqualification; it is the very credential God uses.",
      "Akala natin ang nananalangin ay dapat espirituwal na malakas. Ang twist ng Kaharian: ang nananalangin ay madalas sugatan din. Si Hesus ang Sugatang Manggagamot; \"sa pamamagitan ng Kanyang mga sugat ay gumaling tayo\" (Isaias 53:5). Sabi ni Pablo, inaaliw tayo ng Diyos upang maaliw din natin ang iba sa kaaliwang tinanggap natin (2 Corinto 1:4). Ang sarili nating paglalakbay sa paggaling ay hindi diskwalipikasyon; ito mismo ang kredensiyal na ginagamit ng Diyos."
    ),
    confirm: [
      t("Mark 2:3-5: friends carried the paralyzed man and Jesus saw their faith.", "Marcos 2:3-5: binuhat ng mga kaibigan ang paralitiko at nakita ni Hesus ang kanilang pananampalataya."),
      t("Psalm 147:3: He heals the brokenhearted and binds up their wounds.", "Awit 147:3: pinagagaling Niya ang bagbag na puso at tinatalian ang kanilang mga sugat."),
      t("Luke 10:9: Jesus sent out the seventy to heal the sick and say, \"The kingdom of God has come near.\"", "Lucas 10:9: isinugo ni Hesus ang pitumpu upang magpagaling ng maysakit at sabihing, \"Malapit na ang kaharian ng Diyos.\""),
      t("John 8:36: if the Son sets you free, you will be free indeed.", "Juan 8:36: kung palayain kayo ng Anak, tunay na kayo'y malaya."),
    ],
    heart: [
      t(
        "Pray from compassion, not performance. Let Jesus' tenderness move you to stand with the hurting.",
        "Manalangin mula sa habag, hindi pagpapakitang-gilas. Hayaang ilapit ka ng kalambutan ni Hesus sa mga nasasaktan."
      ),
      t(
        "Trust God with outcomes. Pray in faith, and leave the timing and the way of healing in His hands, without blaming the sick for their lack of healing.",
        "Ipagkatiwala sa Diyos ang kalalabasan. Manalangin nang may pananampalataya, at iwan sa Kanyang mga kamay ang oras at paraan ng paggaling, nang hindi sinisisi ang maysakit."
      ),
    ],
    questions: [
      t("Do I believe that Jesus still heals and sets people free today?", "Naniniwala ba akong nagpapagaling at nagpapalaya pa rin si Hesus ngayon?"),
      t("Whom do I know who is sick, afraid or captive, and have I offered to pray with them?", "Sino ang kilala kong may sakit, natatakot o bihag, at inalok ko na ba silang ipanalangin?"),
      t("Is there something hidden in me that I need to confess to a trusted believer?", "May nakatago ba sa akin na kailangan kong ipagtapat sa mapagkakatiwalaang mananampalataya?"),
      t("How can I pray without pressure, shame or empty promises?", "Paano ako makapananalangin nang walang pamimilit, kahihiyan o walang laman na pangako?"),
    ],
    actions: [
      t("Offer to pray with one person who is hurting this week, in person or by call.", "Mag-alok na ipanalangin ang isang taong nasasaktan ngayong linggo, personal man o tawag."),
      t("Read Luke 4:16-21 and Psalm 147:3 slowly, and ask Jesus to heal something in you.", "Basahin nang dahan-dahan ang Lucas 4:16-21 at Awit 147:3, at hilingin kay Hesus na pagalingin ang bagay sa iyo."),
      t("If you carry a hidden struggle, share it with a mature believer and ask them to pray with you.", "Kung may dala kang lihim na pakikibaka, ibahagi ito sa matandang mananampalataya at hilingin na ipanalangin ka."),
    ],
    prayer: t(
      "Lord Jesus, You came to bring good news to the poor, to free the captives and to heal the brokenhearted. I come to You with my own wounds, and with those of the people I love. Heal what is broken in us, body, mind and spirit. Set free what is bound. Give me compassion, humility and faith when I pray for others, and keep me from pride and pressure. I trust You with the outcomes. Thank You for Your tenderness. In Your name, Amen.",
      "Panginoong Hesus, dumating Ka upang magdala ng mabuting balita sa mga mahihirap, magpalaya sa mga bihag at magpagaling sa mga bagbag ang puso. Lumalapit ako sa Iyo dala ang sarili kong mga sugat, at ang sa mga taong mahal ko. Pagalingin Mo ang sira sa amin, katawan, isip at espiritu. Palayain Mo ang nakagapos. Bigyan Mo ako ng habag, kababaang-loob at pananampalataya kapag nananalangin ako para sa iba, at ilayo Mo ako sa pride at pamimilit. Ipinagkakatiwala ko sa Iyo ang kalalabasan. Salamat sa Iyong kalambutan. Sa pangalan Mo, Amen."
    ),
  },
  "walking-with-someone-in-crisis": {
    revelation: t(
      "In someone's darkest hour they do not need your explanation; they need your presence, which is how God Himself comforts us.",
      "Sa pinakamadilim na oras ng isang tao, hindi niya kailangan ang paliwanag mo; kailangan niya ang presensiya mo, na siyang paraan ng pag-aliw sa atin ng Diyos Mismo."
    ),
    mainTruth: t(
      "\"Rejoice with those who rejoice, weep with those who weep\" (Romans 12:15). Paul blesses \"the Father of mercies and God of all comfort, who comforts us in all our affliction, so that we may be able to comfort those who are in any affliction, with the comfort with which we ourselves are comforted by God\" (2 Corinthians 1:3-4). And \"Bear one another's burdens, and so fulfill the law of Christ\" (Galatians 6:2). Comfort flows through people who have been comforted, and it begins with showing up.",
      "\"Makigalak kayo sa mga nagagalak, makiiyak sa mga umiiyak\" (Roma 12:15). Pinupuri ni Pablo ang \"Ama ng mga awa at Diyos ng buong kaaliwan, na umaaliw sa atin sa lahat ng ating kapighatian, upang maaliw din natin ang mga nasa anumang kapighatian, sa kaaliwang tinanggap natin mula sa Diyos\" (2 Corinto 1:3-4). At \"Pasanin ninyo ang pasanin ng isa't isa, at sa gayon ay matutupad ninyo ang kautusan ni Cristo\" (Galacia 6:2). Dumadaloy ang kaaliwan sa mga taong naaliw na, at nagsisimula ito sa pagpunta."
    ),
    insight: [
      t(
        "Job's friends did the best thing at first: they sat with him on the ground for seven days and said nothing (Job 2:11-13). Their failure began when they opened their mouths to explain his suffering. Many of us rush to give reasons, verses and advice, when the person simply needs a presence. \"Weep with those who weep\" is not \"fix those who weep.\" Silence with love is often more holy than a sermon.",
        "Ginawa ng mga kaibigan ni Job ang pinakamabuti sa simula: umupo sila sa lupa kasama niya nang pitong araw at wala silang sinabi (Job 2:11-13). Nagsimula ang kabiguan nila nang buksan nila ang bibig para ipaliwanag ang pagdurusa niya. Marami sa atin ang nagmamadaling magbigay ng dahilan, talata at payo, gayong presensiya lang ang kailangan ng tao. Ang \"makiiyak sa mga umiiyak\" ay hindi \"ayusin ang umiiyak.\" Ang katahimikang may pag-ibig ay madalas mas banal kaysa sermon."
      ),
      t(
        "Notice that Paul says we can comfort others because we ourselves have been comforted. That does not require a perfect story; it requires an honest one. You do not have to have survived everything. You only have to know that God was near you when you were low. A crisis is a moment when theology becomes personal, and the most helpful words are often, \"I am here, and I am not going anywhere.\"",
        "Pansinin na sinasabi ni Pablo na maaaliw natin ang iba dahil naaliw tayo mismo. Hindi nito kailangan ng perpektong kuwento; kailangan nito ng tapat. Hindi mo kailangang nakaligtas sa lahat. Kailangan mo lang malamang malapit ang Diyos sa iyo noong mababa ka. Ang krisis ay sandaling nagiging personal ang teolohiya, at ang pinakatulong na salita ay madalas, \"Nandito ako, at hindi ako aalis.\""
      ),
    ],
    life: [
      t(
        "A brother in your Gulf fellowship receives a call at midnight: his father has died in the province and he cannot go home because his contract and finances will not allow it. He sits in the stairwell, unable to speak. You sit beside him and say, \"Nandito ako.\" You pray briefly, you help him call his family, you bring food, you check on him the next day and the next week, and you help the group send a gift to his family. That is the Church being the Church.",
        "Ang isang kapatid sa fellowship ninyo sa Gitnang Silangan ay nakatanggap ng tawag sa hatinggabi: namatay ang tatay niya sa probinsya at hindi siya makauwi dahil hindi pinapayagan ng kontrata at pananalapi. Nakaupo siya sa hagdan, hindi makapagsalita. Umupo ka sa tabi niya at sinabing, \"Nandito ako.\" Nagdasal ka nang maikli, tinulungan mo siyang tawagan ang pamilya, nagdala ka ng pagkain, kinumusta mo siya kinabukasan at sa susunod na linggo, at tinulungan mo ang group na magpadala ng regalo sa pamilya niya. Iyan ang Iglesia na ginagampanan ang pagiging Iglesia."
      ),
      t(
        "Know your limits. Some crises, such as suicidal thoughts, abuse, violence or serious mental illness, need professional help and sometimes urgent action. Love says, \"I will walk with you and help you reach the right people.\" Keep a list of local hotlines, your embassy or consulate, trusted doctors and pastors. Respect confidentiality, except when someone's life is in danger.",
        "Alamin ang limitasyon mo. May mga krisis, tulad ng pag-iisip magpakamatay, pang-aabuso, karahasan o malubhang sakit sa isip, na nangangailangan ng propesyonal na tulong at minsan ng agarang aksiyon. Sabi ng pag-ibig, \"Sasamahan kita at tutulungan kitang makarating sa tamang tao.\" Magtago ng listahan ng mga hotline sa lugar, embahada o konsulado, mapagkakatiwalaang doktor at pastor. Igalang ang pagiging kompidensiyal, maliban kung nasa panganib ang buhay ng tao."
      ),
    ],
    twist: t(
      "We assume the helper must be the strong one. The Kingdom twist is that the one who has wept is the one best able to sit with weeping. Jesus Himself wept at Lazarus' tomb, even though He knew He was about to raise him (John 11:35). He did not skip the tears to get to the miracle. If the Lord of life stopped to weep with the grieving, we can slow down and weep as well.",
      "Akala natin ang tumutulong ay dapat ang malakas. Ang twist ng Kaharian: ang taong umiyak na ang pinakamahusay umupo kasama ng umiiyak. Si Hesus mismo ay umiyak sa libingan ni Lazaro, kahit alam Niyang bubuhayin Niya ito (Juan 11:35). Hindi Niya nilaktawan ang luha para marating ang himala. Kung ang Panginoon ng buhay ay huminto para umiyak kasama ng nagdadalamhati, puwede rin tayong magdahan-dahan at umiyak."
    ),
    confirm: [
      t("Psalm 34:18: the Lord is near to the brokenhearted and saves the crushed in spirit.", "Awit 34:18: malapit ang Panginoon sa mga bagbag ang puso at inililigtas ang mga wasak ang espiritu."),
      t("1 Thessalonians 5:14: encourage the fainthearted, help the weak, be patient with all.", "1 Tesalonica 5:14: palakasin ang mahihina ang loob, tulungan ang mahihina, at magtiyaga sa lahat."),
      t("Proverbs 17:17: a friend loves at all times, and a brother is born for adversity.", "Kawikaan 17:17: ang kaibigan ay umiibig sa lahat ng panahon, at ang kapatid ay ipinanganak para sa kagipitan."),
      t("Exodus 17:12: Aaron and Hur held up Moses' tired arms until sunset.", "Exodo 17:12: itinaas nina Aaron at Hur ang pagod na mga kamay ni Moises hanggang lumubog ang araw."),
    ],
    heart: [
      t(
        "Learn to sit with pain without trying to fix it. Let your presence say what words cannot.",
        "Matutong umupo sa tabi ng sakit nang hindi sinusubukang ayusin ito. Hayaang sabihin ng presensiya mo ang hindi masasabi ng salita."
      ),
      t(
        "Stay for the long haul. Crisis fades from other people's attention after a week; you can be the one who remembers and follows up.",
        "Manatili hanggang sa dulo. Nawawala sa atensiyon ng iba ang krisis pagkalipas ng isang linggo; ikaw ang puwedeng maging nakaaalala at kumukumusta."
      ),
    ],
    questions: [
      t("Who around me is in crisis right now and may feel alone?", "Sino sa paligid ko ang nasa krisis ngayon at maaaring nararamdamang nag-iisa?"),
      t("Do I tend to rush to advice, or do I know how to listen?", "Madalas ba akong magmadali sa payo, o marunong ba akong making?"),
      t("What comfort has God given me that I can share with another?", "Anong kaaliwan ang ibinigay sa akin ng Diyos na maibabahagi ko sa iba?"),
      t("Do I know where to refer someone when the crisis is beyond me?", "Alam ko ba kung saan ko ire-refer ang isang tao kapag lampas na sa kaya ko ang krisis?"),
    ],
    actions: [
      t("Reach out today to one person who is suffering, with a call, visit or message that says, \"I am here.\"", "Abutin ngayon ang isang taong nagdurusa, sa tawag, dalaw o mensaheng nagsasabing, \"Nandito ako.\""),
      t("Put a reminder in your phone to follow up with that person in one week and again in one month.", "Maglagay ng paalala sa telepono para kumustahin ang taong iyon pagkaraan ng isang linggo at ulit pagkaraan ng isang buwan."),
      t("Write down emergency contacts and counseling resources you can share when someone needs more help.", "Isulat ang mga emergency contact at counseling resources na maibabahagi mo kapag may nangangailangan ng higit pang tulong."),
    ],
    prayer: t(
      "Father of mercies and God of all comfort, thank You for comforting me in my own afflictions. Make me a person who shows up. Teach me to listen more than I speak, to weep with those who weep, and to carry burdens without judging. Give me wisdom to know when to pray, when to be silent and when to seek help. Heal the broken-hearted around me, and use me as Your hands and Your presence. Let me stay faithful beyond the first week. In Jesus' name, Amen.",
      "Ama ng mga awa at Diyos ng buong kaaliwan, salamat sa pag-aliw Mo sa akin sa sarili kong mga kapighatian. Gawin Mo akong taong pumupunta. Turuan Mo akong making nang higit sa pagsasalita, makiiyak sa mga umiiyak, at magpasan ng pasanin nang hindi humuhusga. Bigyan Mo ako ng karunungang malaman kung kailan mananalangin, tatahimik at hihingi ng tulong. Pagalingin Mo ang mga bagbag ang puso sa paligid ko, at gamitin Mo ako bilang Iyong mga kamay at presensiya. Hayaan Mo akong manatiling tapat lampas sa unang linggo. Sa pangalan ni Hesus, Amen."
    ),
  },
  "teaching-others-to-pray": {
    revelation: t(
      "The best way to teach someone to pray is to let them hear you talk to a Father you really know.",
      "Ang pinakamahusay na paraan para turuan ang isang tao manalangin ay hayaan siyang marinig kang nakikipag-usap sa Amang talagang kilala mo."
    ),
    mainTruth: t(
      "One of the disciples asked Jesus, \"Lord, teach us to pray\" (Luke 11:1). Jesus did not give a lecture; He gave them a relationship and a pattern: \"Father, hallowed be your name. Your kingdom come. Give us each day our daily bread, and forgive us our sins... and lead us not into temptation\" (Luke 11:2-4). Paul adds that we should \"pray at all times in the Spirit, with all prayer and supplication,\" keeping alert with all perseverance, and praying for all the saints and for boldness to speak (Ephesians 6:18-20).",
      "Isa sa mga alagad ang nagtanong kay Hesus, \"Panginoon, turuan Mo kaming manalangin\" (Lucas 11:1). Hindi lektyur ang ibinigay ni Hesus; binigyan Niya sila ng ugnayan at huwaran: \"Ama, sambahin nawa ang Iyong pangalan. Dumating nawa ang Iyong kaharian. Ibigay Mo sa amin araw-araw ang aming pagkain, at patawarin Mo ang aming mga kasalanan... at huwag Mo kaming ihatid sa tukso\" (Lucas 11:2-4). Idinadagdag ni Pablo na \"manalangin sa lahat ng oras sa Espiritu, may buong panalangin at pagsusumamo,\" na nagbabantay nang may buong tiyaga, at ipinapanalangin ang lahat ng banal at ang katapangang magsalita (Efeso 6:18-20)."
    ),
    insight: [
      t(
        "Notice that the disciples had watched Jesus pray, and it made them hungry. The request came from seeing. Prayer is taught by example before explanation. If the people you disciple never hear you pray aloud, they will assume prayer is complicated or only for experts. Let them hear you talk to the Father simply, honestly and specifically: with thanks, with needs, with tears.",
        "Pansinin na pinanood ng mga alagad si Hesus na manalangin, at ginutom sila nito. Ang kahilingan ay nagmula sa nakita nila. Itinuturo ang panalangin sa halimbawa bago sa paliwanag. Kung hindi kailanman maririnig ng dinidisipulo mo na nananalangin ka nang malakas, aakalain nilang kumplikado ito o para lang sa eksperto. Hayaan silang marinig kang nakikipag-usap sa Ama nang simple, tapat at tiyak: may pasasalamat, may pangangailangan, may luha."
      ),
      t(
        "The Lord's Prayer is a pattern, not just a poem to recite. It moves from the Father's name to His kingdom, then to our needs (bread), our relationships (forgiveness) and our battles (temptation). Many new believers think prayer is only asking; this pattern teaches worship first, then request, then confession, then protection. Teach it as a skeleton and let them put flesh on it in their own words.",
        "Ang Panalangin ng Panginoon ay huwaran, hindi lang tula na babanggitin. Mula sa pangalan ng Ama tungo sa Kanyang kaharian, saka sa ating pangangailangan (tinapay), ugnayan (kapatawaran) at laban (tukso). Maraming bagong mananampalataya ang nag-aakalang paghingi lang ang panalangin; itinuturo ng huwarang ito ang pagsamba muna, saka kahilingan, saka pagtatapat, saka proteksiyon. Ituro ito bilang kalansay at hayaan silang dagdagan ng laman sa sarili nilang salita."
      ),
    ],
    life: [
      t(
        "Take Tess, who has just come to faith in her workplace dormitory and says, \"I do not know how to pray; I get so shy.\" Her friend Maricel does not give her a book. She sits with her for ten minutes and says, \"Let us talk to Papa God like we talk to a friend. You say one thing you are thankful for, one thing you need.\" They pray out loud, awkwardly at first. A week later Tess prays on her own at the bus stop. That is discipleship by doing.",
        "Isipin si Tess na kababalik lang sa pananampalataya sa dormitoryo ng trabaho niya at nagsabing, \"Hindi ko alam manalangin; nahihiya ako.\" Hindi siya binigyan ng librong babasahin ng kaibigan niyang si Maricel. Umupo siya sa tabi niya ng sampung minuto at sinabing, \"Kausapin natin si Papa God gaya ng pakikipag-usap sa kaibigan. Magsabi ka ng isang bagay na pinasasalamatan mo, isang bagay na kailangan mo.\" Nanalangin sila nang malakas, may pagkailang sa simula. Pagkaraan ng isang linggo, mag-isang nanalangin si Tess sa bus stop. Iyan ang pagdidisipulo sa pamamagitan ng paggawa."
      ),
      t(
        "Practical helps: use a simple pattern like ACTS (adoration, confession, thanksgiving, supplication) or the Lord's Prayer; pray short, honest sentences; invite them to pray aloud for one thing; keep a small prayer list; and celebrate answers together. Remind them that God is not impressed by long words; He listens to the heart of a child.",
        "Praktikal na tulong: gumamit ng simpleng huwaran gaya ng ACTS (pagsamba, pagtatapat, pasasalamat, pagsusumamo) o ng Panalangin ng Panginoon; manalangin ng maiikli at tapat na pangungusap; anyayahan silang magdasal nang malakas para sa isang bagay; magtago ng maliit na listahan ng panalangin; at ipagdiwang nang sama-sama ang mga sagot. Ipaalala na hindi napapahanga ang Diyos ng mahahabang salita; pinakikinggan Niya ang puso ng bata."
      ),
    ],
    twist: t(
      "We think prayer is a skill that experts master and teach. The Kingdom twist is that prayer is a relationship, and the best teacher is the one who is most dependent. Jesus said we must come as little children (Mark 10:15). The one who teaches prayer best is not the most eloquent, but the one who keeps coming back to the Father with open hands.",
      "Akala natin ang panalangin ay kasanayang pinagkakadalubhasaan ng mga eksperto. Ang twist ng Kaharian: ang panalangin ay ugnayan, at ang pinakamahusay na guro ay ang pinakamaasa. Sabi ni Hesus, dapat tayong lumapit na gaya ng maliliit na bata (Marcos 10:15). Ang pinakamahusay magturo ng panalangin ay hindi ang pinakamahusay magsalita, kundi ang paulit-ulit na bumabalik sa Ama na bukas ang mga kamay."
    ),
    confirm: [
      t("Matthew 6:5-8: pray in secret, without empty phrases; your Father knows what you need.", "Mateo 6:5-8: manalangin nang lihim, walang kabuluhang pag-uulit; alam ng Ama ang kailangan ninyo."),
      t("Luke 18:1: Jesus told a parable that they ought always to pray and not lose heart.", "Lucas 18:1: nagsalaysay si Hesus ng talinghaga na dapat laging manalangin at huwag manghina."),
      t("Acts 4:23-31: the believers prayed together and the place was shaken.", "Gawa 4:23-31: nanalangin nang sama-sama ang mga mananampalataya at nayanig ang lugar."),
      t("Romans 8:26: the Spirit helps us in our weakness, for we do not know what to pray for as we ought.", "Roma 8:26: tinutulungan tayo ng Espiritu sa ating kahinaan, sapagkat hindi natin alam kung ano ang dapat ipanalangin."),
    ],
    heart: [
      t(
        "Pray in front of others, even if it feels awkward. Your simple faith may teach more than a perfect sermon.",
        "Manalangin sa harap ng iba, kahit nakakailang. Mas maituturo ng simple mong pananampalataya kaysa sa perpektong sermon."
      ),
      t(
        "Be patient with beginners. Never mock a clumsy prayer; rejoice that they are talking to God at all.",
        "Magtiyaga sa mga nagsisimula. Huwag kailanman pagtawanan ang magulong dasal; magalak na kinakausap na nila ang Diyos."
      ),
    ],
    questions: [
      t("Do the people I disciple ever hear me pray, or only talk about prayer?", "Naririnig ba ng dinidisipulo ko na nananalangin ako, o nagsasalita lang ako tungkol sa panalangin?"),
      t("Which part of the Lord's Prayer do I most neglect in my own prayers?", "Aling bahagi ng Panalangin ng Panginoon ang pinakanakakaligtaan ko sa sarili kong dasal?"),
      t("What simple pattern could I teach a new believer this week?", "Anong simpleng huwaran ang maituturo ko sa bagong mananampalataya ngayong linggo?"),
      t("Who needs me to pray with them, not just for them?", "Sino ang nangangailangan na manalangin ako kasama nila, hindi lang para sa kanila?"),
    ],
    actions: [
      t("Pray aloud with one person this week, keeping it short and simple.", "Manalangin nang malakas kasama ang isang tao ngayong linggo, maikli at simple."),
      t("Teach the Lord's Prayer as a pattern: pray each line slowly and add your own words.", "Ituro ang Panalangin ng Panginoon bilang huwaran: ipanalangin nang dahan-dahan ang bawat linya at dagdagan ng sariling salita."),
      t("Start a shared prayer list with a friend and check back on answers in a month.", "Magsimula ng pinagsamang listahan ng panalangin kasama ng kaibigan at balikan ang mga sagot pagkaraan ng isang buwan."),
    ],
    prayer: t(
      "Father, thank You that we can come to You as children. Teach me to pray, and teach me to teach others. Let those I disciple hear in my prayers a real relationship with You. Make me patient with beginners and honest with my own struggles. Show me how to pray in the Spirit, with perseverance, for the saints and for boldness. Help me to pray with people and not only for them. May a generation of praying believers rise through our lives. In Jesus' name, Amen.",
      "Ama, salamat at puwede kaming lumapit sa Iyo bilang mga anak. Turuan Mo akong manalangin, at turuan Mo akong magturo sa iba. Hayaang marinig ng mga dinidisipulo ko sa mga dasal ko ang tunay na ugnayan sa Iyo. Gawin Mo akong matiyaga sa mga nagsisimula at tapat sa sarili kong pakikibaka. Ipakita Mo kung paano manalangin sa Espiritu, nang may tiyaga, para sa mga banal at sa katapangan. Tulungan Mo akong manalangin kasama ng tao at hindi lang para sa kanila. Magbangon nawa ng salinlahi ng nananalanging mananampalataya sa pamamagitan ng aming buhay. Sa pangalan ni Hesus, Amen."
    ),
  },
};
